-- ----------------------------
-- Table structure for app_user_cash_out_order
-- ----------------------------
DROP TABLE IF EXISTS `app_user_cash_out_order`;
CREATE TABLE `app_user_cash_out_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `user_id` bigint DEFAULT NULL COMMENT '用户id',
  `user_group` int DEFAULT NULL COMMENT '正常 0 假人 1',
  `user_account` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '用户名',
  `top_user_id` bigint DEFAULT NULL COMMENT '总代用户ID',
  `ip` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'ip',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '订单编号',
  `apply_time` datetime DEFAULT NULL COMMENT '申请时间',
  `apply_amount` decimal(18,2) DEFAULT NULL COMMENT '申请提现金额',
  `actual_amount` decimal(18,2) DEFAULT NULL COMMENT '实际打款金额',
  `fee` decimal(18,2) DEFAULT NULL COMMENT '手续费',
  `full_name` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '真实姓名',
  `net_work` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '提现网络 Tron Eth',
  `address` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '钱包地址',
  `mobile_phone` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '提现手机号',
  `remark` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '用户备注',
  `remit_time` datetime DEFAULT NULL COMMENT '审核时间',
  `cash_status` int DEFAULT NULL COMMENT '订单类型 1待处理 2已锁定 3已取消 4已拒绝 5已成功',
  `reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '失败原因,如果有',
  `hash` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT 'hash,如果有',
  `operator_user` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '订单处理--操作人账号',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_order_no` (`order_no`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_cash_status` (`cash_status`) USING BTREE,
  KEY `idx_apply_time` (`apply_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=8 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户提现订单表';

