-- ----------------------------
-- Table structure for app_user_finance_stats
-- ----------------------------
DROP TABLE IF EXISTS `app_user_finance_stats`;
CREATE TABLE `app_user_finance_stats` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `top_user_id` bigint DEFAULT NULL COMMENT '总代用户ID',
  `total_recharge` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '累计充值',
  `total_withdraw` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '累计提现',
  `total_income` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '累计收入',
  `total_commission` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '累计佣金',
  `total_trading_volume` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '累计交易量',
  `last_recharge_time` datetime DEFAULT NULL COMMENT '最后充值时间',
  `last_withdraw_time` datetime DEFAULT NULL COMMENT '最后提现时间',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_id` (`user_id`) USING BTREE,
  KEY `idx_top_user_id` (`top_user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户资金统计表';

