-- ----------------------------
-- Table structure for app_user_gold_change
-- ----------------------------
DROP TABLE IF EXISTS `app_user_gold_change`;
CREATE TABLE `app_user_gold_change` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '账表id',
  `serial_no` varchar(100) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT '账变流水号',
  `user_id` bigint DEFAULT NULL COMMENT '用户id',
  `top_user_id` bigint NOT NULL DEFAULT '-1' COMMENT '总代用户ID',
  `asset_type` int DEFAULT '0' COMMENT '资产类型 0：余额 1：冻结金额',
  `user_account` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '会员账号',
  `change_type` int DEFAULT '0' COMMENT '变动类型',
  `before_amount` decimal(20,2) DEFAULT NULL COMMENT '变动前金额',
  `after_amount` decimal(20,2) DEFAULT NULL COMMENT '变动后金额',
  `amount` decimal(20,2) DEFAULT NULL COMMENT '账变金额',
  `op_note` varchar(255) CHARACTER SET utf8mb3 COLLATE utf8mb3_unicode_ci DEFAULT NULL COMMENT '操作说明',
  `create_time` timestamp NULL DEFAULT NULL COMMENT '创建时间',
  `user_group` int DEFAULT '0' COMMENT '正常0 假人1',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=85 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='会员账变记录表';

-- ----------------------------
-- Records of app_user_gold_change
-- ----------------------------
BEGIN;
COMMIT;

-- ----------------------------
-- Table structure for app_user_wallet
-- ----------------------------
DROP TABLE IF EXISTS `app_user_wallet`;
CREATE TABLE `app_user_wallet` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `top_user_id` bigint DEFAULT NULL COMMENT '总代用户ID',
  `wallet_type` tinyint NOT NULL DEFAULT '0' COMMENT '钱包类型：0-主钱包，1-交易钱包，2-冻结钱包',
  `currency_code` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'CNY' COMMENT '币种代码',
  `available_balance` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '可用余额',
  `frozen_balance` decimal(20,4) NOT NULL DEFAULT '0.0000' COMMENT '冻结余额',
  `total_balance` decimal(20,4) GENERATED ALWAYS AS ((`available_balance` + `frozen_balance`)) STORED COMMENT '总余额（计算字段）',
  `credit_score` int DEFAULT '100' COMMENT '信誉分 0-100',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0-禁用，1-正常，2-冻结',
  `version` int NOT NULL DEFAULT '0' COMMENT '版本号（乐观锁）',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_user_wallet_type_currency` (`user_id`,`wallet_type`,`currency_code`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_top_user_id` (`top_user_id`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户钱包表V2';

