-- ----------------------------
-- Table structure for app_wallet_operation_log
-- ----------------------------
DROP TABLE IF EXISTS `app_wallet_operation_log`;
CREATE TABLE `app_wallet_operation_log` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `serial_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '流水号',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `wallet_type` tinyint NOT NULL COMMENT '钱包类型',
  `operation_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '操作类型',
  `amount` decimal(20,4) NOT NULL COMMENT '操作金额',
  `before_balance` decimal(20,4) NOT NULL COMMENT '操作前余额',
  `after_balance` decimal(20,4) NOT NULL COMMENT '操作后余额',
  `related_id` bigint DEFAULT NULL COMMENT '关联业务ID',
  `related_type` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '关联业务类型',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：0-失败，1-成功，2-处理中',
  `remark` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_serial_no` (`serial_no`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_operation_type` (`operation_type`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=44 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='钱包操作日志表';

