-- ----------------------------
-- Table structure for financial_order
-- ----------------------------
DROP TABLE IF EXISTS `financial_order`;
CREATE TABLE `financial_order` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '订单编号',
  `product_id` bigint NOT NULL COMMENT '理财产品ID',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '产品编码（冗余）',
  `product_name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '产品名称（冗余）',
  `invest_amount` decimal(20,6) NOT NULL COMMENT '投资金额',
  `invest_period` int DEFAULT NULL COMMENT '投资期限（天数），活期可为空',
  `coin` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'USD' COMMENT '结算币种',
  `rate_type` tinyint NOT NULL DEFAULT '1' COMMENT '利率类型：1-活期 2-固定',
  `min_rate` decimal(10,4) DEFAULT NULL COMMENT '最小利率',
  `max_rate` decimal(10,4) DEFAULT NULL COMMENT '最大利率',
  `default_rate` decimal(10,4) DEFAULT NULL COMMENT '违约/基准利率',
  `actual_rate` decimal(10,4) DEFAULT NULL COMMENT '实际生效利率',
  `order_status` tinyint NOT NULL DEFAULT '1' COMMENT '订单状态：1-生效中 2-已平仓 3-已过期',
  `start_time` datetime NOT NULL COMMENT '开始计息时间',
  `next_settle_time` datetime DEFAULT NULL COMMENT '下次结算时间',
  `expire_time` datetime DEFAULT NULL COMMENT '到期时间（固定期限适用）',
  `close_time` datetime DEFAULT NULL COMMENT '实际平仓/结束时间',
  `accumulated_profit` decimal(20,6) NOT NULL DEFAULT '0.000000' COMMENT '累计收益',
  `last_profit` decimal(20,6) DEFAULT NULL COMMENT '上次结算收益',
  `settled_count` int DEFAULT '0' COMMENT '已结算次数',
  `settle_cycle` varchar(16) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '结算周期：daily/weekly/monthly',
  `wallet_type` tinyint DEFAULT '0' COMMENT '扣款钱包类型：0-主钱包 1-交易钱包',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '订单备注',
  `apply_time` datetime NOT NULL COMMENT '申购时间',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_order_no` (`order_no`) USING BTREE,
  KEY `idx_user_id_status` (`user_id`,`order_status`) USING BTREE,
  KEY `idx_product_id` (`product_id`) USING BTREE,
  KEY `idx_apply_time` (`apply_time`) USING BTREE,
  KEY `idx_expire_time` (`expire_time`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='理财订单表';

