-- ----------------------------
-- Table structure for financial_product
-- ----------------------------
DROP TABLE IF EXISTS `financial_product`;
CREATE TABLE `financial_product` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `product_code` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '产品唯一编码',
  `title` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL COMMENT '产品标题',
  `icon_url` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '产品图标',
  `status` tinyint NOT NULL DEFAULT '1' COMMENT '状态：1-上架 0-下架',
  `days` int DEFAULT NULL COMMENT '周期/天数；活期可为空',
  `rate_type` tinyint NOT NULL DEFAULT '1' COMMENT '利率类型：1-活期 2-固定',
  `default_rate` decimal(10,4) DEFAULT NULL COMMENT '默认收益率(例如违约/目标年化)',
  `min_rate` decimal(10,4) DEFAULT NULL COMMENT '最低收益率或浮动下限',
  `max_rate` decimal(10,4) DEFAULT NULL COMMENT '最高收益率或浮动上限',
  `time_limit` tinyint NOT NULL DEFAULT '0' COMMENT '限购类型：0-不限 1-限时 2-限量等业务自定义',
  `limit_min_amount` decimal(20,6) DEFAULT NULL COMMENT '单笔最小申购金额',
  `limit_max_amount` decimal(20,6) DEFAULT NULL COMMENT '单笔最大申购金额',
  `coin` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT 'USD' COMMENT '结算币种',
  `classify` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '自定义分类标签，如0-股票型',
  `is_hot` tinyint NOT NULL DEFAULT '0' COMMENT '是否热门：0-否 1-是',
  `sort` int DEFAULT NULL COMMENT '排序值，越大越靠前',
  `level` tinyint DEFAULT '0' COMMENT '面向等级/用户组，可选',
  `basic_invest_amount` decimal(24,6) DEFAULT NULL COMMENT '基础筹资额（平台自有或基准）',
  `total_invest_amount` decimal(24,6) DEFAULT NULL COMMENT '目标筹资总额',
  `purchased_amount` decimal(24,6) DEFAULT '0.000000' COMMENT '已购金额',
  `remain_amount` decimal(24,6) DEFAULT '0.000000' COMMENT '剩余可购金额',
  `avg_rate` decimal(10,4) DEFAULT NULL COMMENT '当前平均收益率(展示用)',
  `buy_purchase` bigint DEFAULT '0' COMMENT '累计购买人数/笔数',
  `remark` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注/公告',
  `product_intro` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '产品介绍',
  `faq` text CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci COMMENT '问答/风险提示等',
  `platform_risk_rate` decimal(10,4) DEFAULT NULL COMMENT '平台违约率/风险提示用',
  `daily_rate` decimal(10,4) DEFAULT NULL COMMENT '参考日收益率(非必填)',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_product_code` (`product_code`) USING BTREE,
  KEY `idx_status_sort` (`status`,`sort`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='理财产品信息表';

