-- ----------------------------
-- Table structure for ipo
-- ----------------------------
DROP TABLE IF EXISTS `ipo`;
CREATE TABLE `ipo` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '名字',
  `country` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '国家',
  `symbol` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '产品代码',
  `open_date` datetime DEFAULT NULL COMMENT '开始时间',
  `close_date` datetime DEFAULT NULL COMMENT '结束时间',
  `listing_date` datetime DEFAULT NULL COMMENT '上市时间',
  `price` decimal(20,4) DEFAULT NULL COMMENT '价格',
  `count` bigint DEFAULT NULL COMMENT '认购数量',
  `exchange` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '交易所名称',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态，1:认购中，2:结束',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `type` int NOT NULL DEFAULT '1' COMMENT '1:新股，2:线下配售',
  `is_lock` int NOT NULL DEFAULT '0' COMMENT '新股申购，已认缴后，转持仓是否锁仓是否锁仓（0: 未锁仓, 1: 锁仓）',
  `subscription_time` datetime NOT NULL COMMENT '认缴时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=11 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='IPO信息表';

