-- ----------------------------
-- Table structure for rising_falling_sectors
-- ----------------------------
DROP TABLE IF EXISTS `rising_falling_sectors`;
CREATE TABLE `rising_falling_sectors` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `symbol` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '交易对',
  `stock_id` bigint NOT NULL COMMENT 'stock 的id',
  `stock_lock_status` int DEFAULT NULL COMMENT '股票锁定状态',
  `display_status` int NOT NULL DEFAULT '0' COMMENT '显示状态(0:显示，1:隐藏)',
  `open_time` datetime NOT NULL COMMENT '开始时间',
  `end_time` datetime NOT NULL COMMENT '结束时间',
  `start_sell_time` datetime NOT NULL COMMENT '开始售卖时间',
  `end_sell_time` datetime NOT NULL COMMENT '结束售卖的时间',
  `create_time` datetime NOT NULL COMMENT '创建时间',
  `pass_word` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '密码',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_stock_id` (`stock_id`) USING BTREE COMMENT '股票ID索引',
  KEY `idx_display_status` (`display_status`) USING BTREE COMMENT '显示状态索引',
  KEY `idx_open_time` (`open_time`) USING BTREE COMMENT '开始时间索引',
  KEY `idx_end_time` (`end_time`) USING BTREE COMMENT '结束时间索引',
  KEY `idx_create_time` (`create_time`) USING BTREE COMMENT '创建时间索引'
) ENGINE=InnoDB AUTO_INCREMENT=4 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='涨跌板块';

-- ----------------------------
-- Records of rising_falling_sectors
-- ----------------------------
