-- ----------------------------
-- Table structure for rising_falling_sectors_subscription
-- ----------------------------
DROP TABLE IF EXISTS `rising_falling_sectors_subscription`;
CREATE TABLE `rising_falling_sectors_subscription` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `rising_falling_sectors_id` bigint DEFAULT NULL COMMENT '涨跌板块ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '订单号',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `top_user_id` bigint DEFAULT NULL COMMENT '上级用户ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '股票名称',
  `stock_id` bigint DEFAULT NULL COMMENT '股票ID',
  `symbol` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '交易对',
  `buy_price` decimal(20,8) DEFAULT NULL COMMENT '购买价格',
  `apply_nums` decimal(20,4) DEFAULT NULL COMMENT '申购数量',
  `actual_amount` decimal(20,8) DEFAULT NULL COMMENT '实际支付金额',
  `status` int DEFAULT NULL COMMENT '状态：1、已申购，2、已取消，3、已确认，4、已转持仓',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_rising_falling_sectors_id` (`rising_falling_sectors_id`) USING BTREE,
  KEY `idx_order_no` (`order_no`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_symbol` (`symbol`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=3 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='涨跌板块申购记录表';

