-- ----------------------------
-- Table structure for stock
-- ----------------------------
DROP TABLE IF EXISTS `stock`;
CREATE TABLE `stock` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `p_id` bigint DEFAULT NULL COMMENT '股票唯一ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '股票名称',
  `symbol` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '股票代码',
  `is_cfd` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '是否为CFD合约',
  `high` decimal(15,4) DEFAULT NULL COMMENT '当日最高价',
  `low` decimal(15,4) DEFAULT NULL COMMENT '当日最低价',
  `last` decimal(15,4) DEFAULT NULL COMMENT '最新成交价',
  `last_pair_decimal` int DEFAULT NULL COMMENT '价格小数位数',
  `chg` decimal(15,4) DEFAULT NULL COMMENT '当日价格变动额',
  `chg_pct` decimal(6,2) DEFAULT NULL COMMENT '当日价格变动百分比(%)',
  `volume` bigint DEFAULT NULL COMMENT '当日成交量',
  `avg_volume` bigint DEFAULT NULL COMMENT '平均成交量',
  `time` bigint DEFAULT NULL COMMENT '时间戳(Unix)',
  `is_open` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '是否开市(0=休市, 1=开市)',
  `url` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '股票详情URL(相对路径)',
  `flag` char(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '国家代码(ISO两位)',
  `country_name_translated` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '国家名称(翻译)',
  `exchange_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '交易所ID',
  `performance_day` decimal(6,2) DEFAULT NULL COMMENT '当日涨跌幅(%)',
  `performance_week` decimal(6,2) DEFAULT NULL COMMENT '近1周涨跌幅(%)',
  `performance_month` decimal(6,2) DEFAULT NULL COMMENT '近1月涨跌幅(%)',
  `performance_ytd` decimal(6,2) DEFAULT NULL COMMENT '年初至今涨跌幅(%)',
  `performance_year` decimal(6,2) DEFAULT NULL COMMENT '近1年涨跌幅(%)',
  `performance_3year` decimal(6,2) DEFAULT NULL COMMENT '近3年涨跌幅(%)',
  `technical_hour` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '小时级技术面建议',
  `technical_day` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '日级技术面建议',
  `technical_week` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '周级技术面建议',
  `technical_month` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '月级技术面建议',
  `fundamental_market_cap` bigint DEFAULT NULL COMMENT '市值(货币单位同交易所)',
  `fundamental_revenue` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '营收(带单位的字符串)',
  `fundamental_ratio` decimal(10,2) DEFAULT NULL COMMENT '市盈率(PE)',
  `fundamental_beta` decimal(10,2) DEFAULT NULL COMMENT 'Beta系数',
  `pair_type` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '产品类型(如Equities)',
  `source_type` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '数据来源',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_symbol` (`symbol`) USING BTREE,
  KEY `idx_country` (`flag`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=54 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='股票行情数据表';

