-- ----------------------------
-- Table structure for stock_block_trade
-- ----------------------------
DROP TABLE IF EXISTS `stock_block_trade`;
CREATE TABLE `stock_block_trade` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '股票名称',
  `stock_id` int DEFAULT NULL COMMENT '股票id',
  `max_amount` decimal(10,2) DEFAULT '0.00' COMMENT '最大买入数量',
  `min_amount` decimal(10,2) DEFAULT NULL COMMENT '最小买入数量',
  `lock_status` int DEFAULT NULL COMMENT '锁定状态，1:锁定，2:不锁定',
  `status` int DEFAULT NULL COMMENT '状态',
  `discount` decimal(6,4) DEFAULT NULL COMMENT '折扣',
  `start_date_time` datetime DEFAULT NULL COMMENT '开始售卖时间',
  `end_date_time` datetime DEFAULT NULL COMMENT '结束售卖时间',
  `release_look_time` datetime DEFAULT NULL COMMENT '释放时间',
  `first_release_look_rate` decimal(6,4) DEFAULT NULL COMMENT '第一次释放比例',
  `first_release_look_date_time` datetime DEFAULT NULL COMMENT '第一次释放时间',
  PRIMARY KEY (`id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=7 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='股票大宗交易';

-- ----------------------------
-- Records of stock_block_trade
-- ----------------------------
BEGIN;
INSERT INTO `stock_block_trade` (`id`, `name`, `stock_id`, `max_amount`, `min_amount`, `lock_status`, `status`, `discount`, `start_date_time`, `end_date_time`, `release_look_time`, `first_release_look_rate`, `first_release_look_date_time`) VALUES (5, '大宗交易测试', 4045, 123.00, 1230.00, 0, 1, 0.8000, '2025-12-18 00:00:00', '2026-01-14 00:00:00', '2025-12-23 00:00:00', NULL, NULL);
INSERT INTO `stock_block_trade` (`id`, `name`, `stock_id`, `max_amount`, `min_amount`, `lock_status`, `status`, `discount`, `start_date_time`, `end_date_time`, `release_look_time`, `first_release_look_rate`, `first_release_look_date_time`) VALUES (6, '大宗交易测试2', 4045, 1111111.00, 11.00, 0, 1, 0.8000, '2025-12-01 00:00:00', '2026-01-12 00:00:00', '2025-12-16 00:00:00', NULL, NULL);
COMMIT;

-- ----------------------------
-- Table structure for stock_block_trade_subscription
-- ----------------------------
DROP TABLE IF EXISTS `stock_block_trade_subscription`;
CREATE TABLE `stock_block_trade_subscription` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `block_trade_id` bigint DEFAULT NULL COMMENT '大宗交易ID',
  `order_no` varchar(64) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '订单号',
  `user_id` bigint DEFAULT NULL COMMENT '用户ID',
  `top_user_id` bigint DEFAULT NULL COMMENT '上级用户ID',
  `name` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '股票名称',
  `stock_id` bigint DEFAULT NULL COMMENT '股票ID',
  `buy_price` decimal(20,8) DEFAULT NULL COMMENT '购买价格',
  `apply_nums` decimal(20,4) DEFAULT NULL COMMENT '申购数量',
  `discount` decimal(10,4) DEFAULT NULL COMMENT '折扣',
  `actual_amount` decimal(20,8) DEFAULT NULL COMMENT '实际支付金额',
  `status` int DEFAULT NULL COMMENT '状态：1、已申购，2、已取消，3、已确认，4、已转持仓',
  `create_time` datetime DEFAULT NULL COMMENT '创建时间',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `confirm_time` datetime DEFAULT NULL COMMENT '确认时间',
  `remarks` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci DEFAULT NULL COMMENT '备注',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
