-- ----------------------------
DROP TABLE IF EXISTS `stock_index`;
CREATE TABLE `stock_index` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `name` varchar(255) DEFAULT NULL COMMENT '名称',
