-- ----------------------------
-- Table structure for stock_news
-- ----------------------------
DROP TABLE IF EXISTS `stock_news`;
CREATE TABLE `stock_news` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键ID',
  `title` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新闻标题',
  `provider` varchar(128) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新闻来源',
  `link` varchar(512) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '新闻链接',
  `content` longtext CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci COMMENT '新闻详情内容',
  `create_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT 'system' COMMENT '创建人',
  `create_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_by` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '更新人',
  `update_time` timestamp NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  PRIMARY KEY (`id`) USING BTREE,
  KEY `idx_provider` (`provider`) USING BTREE COMMENT '新闻来源索引',
  KEY `idx_create_time` (`create_time` DESC) USING BTREE COMMENT '创建时间索引'
) ENGINE=InnoDB AUTO_INCREMENT=36 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='股票新闻表';

-- ----------------------------
-- Records of stock_news
-- ----------------------------
BEGIN;
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (1, 'X3 Holdings stock drops after announcing 1-for-6 share consolidation', 'Investing.com', 'https://www.investing.com/news/stock-market-news/x3-holdings-stock-drops-after-announcing-1for6-share-consolidation-93CH-4423166', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEC0409P_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/powerbridge\" id=\"1884cfe309f9397b\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1127917\">X3 Holdings Co Ltd (NASDAQ:XTKG)</a></span> stock fell 7.7% on Friday after the company announced plans for a 1-for-6 share consolidation and a significant reduction in par value of its ordinary shares.</p><br/><p>The global provider of digital solutions and technology services said the share consolidation will become effective on December 30, 2025, following approval from shareholders at an extraordinary general meeting held in February. Simultaneously, the company will reduce the par value of its ordinary shares from $48.00 to $0.00003 per share through a capital reduction.</p><br/><p>On April 10, 2025, <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">X3 Holdings</span></span> received approval from the Grand Court of the Cayman Islands for the capital reduction and completed registration with the Cayman Islands Registrar of Companies. The company’s authorized share capital is now $150,000 divided into 4.98 billion Class A ordinary shares and 20 million Class B ordinary shares, each with a par value of $0.00003.</p><br/><p>The company’s Class A ordinary shares will continue trading on the Nasdaq Capital Market under the symbol \"XTKG\" but with a new CUSIP number (G72007142) when trading begins on a post-capital reduction basis on December 30, 2025.</p><br/><p>As part of the consolidation, every six shares will automatically be combined into one ordinary share. Outstanding warrants and other equity rights will be adjusted proportionately to reflect the change. Shareholders entitled to fractional shares will receive cash instead, and the company’s transfer agent will provide instructions to shareholders holding stock certificates.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (2, 'Target faces activist investor pressure amid sales decline, FT reports', 'Reuters', 'https://www.investing.com/news/stock-market-news/pressure-grows-on-target-as-activist-investor-builds-stake-ft-reports-4423154', '<img src=\"https://i-invdn-com.investing.com/trkd-images/LYNXMPELBP0EH_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Dec 26 (Reuters) - <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/target\" id=\"1884cf9ba7c036c2\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"8180\">Target</a></span> is facing pressure from hedge fund Toms Capital Investment Management, which has made a significant investment in the retailer, the Financial Times reported on Friday, citing people familiar with the matter.</p><br/><p>Shares of the company were up 1.5% after the news. The stock has lost about 26% of its value this year.</p><br/><p>The Minneapolis-based retailer has posted three straight quarters of falling comparable sales and is betting on incoming chief and longtime company executive Michael Fiddelke to revive growth, as the business faces pressure from strained household budgets and tariff uncertainties.</p><br/><p>Meanwhile, rival <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/wal-mart-stores\" id=\"1884cf9ba7fa6a94\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"7997\">Walmart</a></span> has gained market share with its focus on cheap groceries and household essentials, coupled with fast doorstep delivery.</p><br/><p>\"As part of our robust shareholder engagement program, we maintain a regular dialogue with the investment community. Target’s top priority is getting back to growth...,\" <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Target</span></span> said in a statement to Reuters.</p><br/><p>Target has plans to spend an additional $1 billion in 2026 on new store openings and remodels. It has also cut 1,800 corporate roles as part of a broader restructuring.</p><br/><p></p><br/><p>Earlier this year, Toms Capital had built a stake in Tylenol maker <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Kenvue</span></span> before its sale to <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/kimberly-clark\" id=\"1884cf9ba8533c36\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"269\">Kimberly-Clark</a></span> last month for $40 billion.</p><br/><p>Toms Capital did not immediately respond to a Reuters request for comment. &nbsp;</p><br/><p></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (3, 'Coupang and Xpeng among market cap stock movers on Friday', 'Investing.com', 'https://www.investing.com/news/stock-market-news/coupang-and-xpeng-among-market-cap-stock-movers-on-friday-93CH-4423157', '<img src=\"https://i-invdn-com.investing.com/news/DanielSchreiberandShaiWiningerLemonadeco-founders_800x533_L_1652163358.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Friday’s market has seen swings in various stocks based on news and other factors. Today, stocks like <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/coupang-llc\" id=\"1884cdc2965a85ea\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1171204\">Coupang (CPNG)</a></span> and <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/xpeng-inc\" id=\"1884cdc296967cfc\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1165509\">Xpeng (XPEV)</a></span> are rallying, while stocks like <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/dmy-technology-group-iii\" id=\"1884cdc296be672b\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1168961\">dMY Technology Group III (<span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">IONQ</span></span>)</a></span> are falling. Below are highlights of some of the biggest stock movers, from mega-caps to small caps.</p><br/><p>Large-Cap Stock Movers ($10-$200 billion USD)</p><br/><p></p><br/><p></p><br/><p>Mid-Cap Stock Movers ($2-$10 billion USD)</p><br/><p></p><br/><p></p><br/><p>Small-Cap Stock Movers ($300 million - $2 billion USD)</p><br/><p></p><br/><p></p><br/><p>For real-time, market-moving news, join Investing Pro.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (4, 'Turkey stocks lower at close of trade; BIST 100 down 0.37%', 'Investing.com', 'https://www.investing.com/news/stock-market-news/turkey-stocks-lower-at-close-of-trade-bist-100-down-037-4423156', '<img src=\"https://i-invdn-com.investing.com/news/Istanbul Stock Exchange_800x533_L_1428571883.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com – Turkey stocks were lower after the close on Friday, as losses in the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/ise-telecommunication\" id=\"1884cd979ae5bad0\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19177\">Telecoms</a></span>, <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/ise-non-metal-min.product\" id=\"1884cd979b1dbe98\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19169\">Non-Metal Mineral Products</a></span> and <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/ise-wood,paper,printing\" id=\"1884cd979b56db5a\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19167\">Wood, Paper &amp; Printing</a></span> sectors led shares lower.</p><br/><p>At the close in Istanbul, the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/ise-100\" id=\"1884cd979baf05d9\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19155\">BIST 100</a></span> declined 0.37%.</p><br/><p>The best performers of the session on the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/ise-100\" id=\"1884cd979baf05d9\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19155\">BIST 100</a></span> were Europower Enerji ve Otomasyon Teknolojileri Sanayi Ticaret AS (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/europower-enerji-ve-otomasyon\" id=\"1884cd979c33bc4e\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1202199\">EUPWR</a></span>), which rose 6.67% or 2.10 points to trade at 33.58 at the close. Meanwhile, Margun Enerji Uretim Sanayi ve Ticaret AS (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/margun-enerji-uretim-sanayi\" id=\"1884cd979c6423e7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1177677\">MAGEN</a></span>) added 6.49% or 2.38 points to end at 39.08 and Aksa Enerji Uretim AS (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/aksa-enerji-uretim\" id=\"1884cd979c934958\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19272\">AKSEN</a></span>) was up 6.08% or 3.90 points to 68.00 in late trade.</p><br/><p>The worst performers of the session were Tekfen Holding AS (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/tekfen-holding\" id=\"1884cd979cbe976c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19583\">TKFEN</a></span>), which fell 7.69% or 6.00 points to trade at 72.00 at the close. Efor Yatırım Sanayi ve Ticaret A.Ş. (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/efor-cay-sanayi-tic-as\" id=\"1884cd979cf53b03\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1217794\">EFOR</a></span>) declined 5.78% or 1.54 points to end at 25.10 and Kardemir Karabuk Demir Celik Sanayi ve Ticaret AS Class D (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/kardemir-(d)\" id=\"1884cd979d26fb78\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19487\">KRDMD</a></span>) was down 3.48% or 0.94 points to 26.06.</p><br/><p>Falling stocks outnumbered advancing ones on the Istanbul Stock Exchange by 346 to 238 and 21 ended unchanged.</p><br/><p>Shares in Margun Enerji Uretim Sanayi ve Ticaret AS (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/margun-enerji-uretim-sanayi\" id=\"1884cd979c6423e7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1177677\">MAGEN</a></span>) rose to all time highs; up 6.49% or 2.38 to 39.08. Shares in Aksa Enerji Uretim AS (IS:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/aksa-enerji-uretim\" id=\"1884cd979c934958\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19272\">AKSEN</a></span>) rose to all time highs; rising 6.08% or 3.90 to 68.00.</p><br/><p>Gold Futures for February delivery was up 1.42% or 63.95 to $4,566.75 a troy ounce. Elsewhere in commodities trading, Crude oil for delivery in February fell 1.08% or 0.63 to hit $57.72 a barrel, while the February Brent oil contract fell 1.12% or 0.70 to trade at $61.54 a barrel.</p><br/><p>USD/TRY was up 0.16% to 42.91, while EUR/TRY rose 0.18% to 50.67.</p><br/><p>The US Dollar Index Futures was down 0.12% at 97.57.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (5, 'Morocco stocks lower at close of trade; Moroccan All Shares down 2.45%', 'Investing.com', 'https://www.investing.com/news/stock-market-news/morocco-stocks-lower-at-close-of-trade-moroccan-all-shares-down-245-4423153', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEA6606G_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com – Morocco stocks were lower after the close on Friday, as losses in the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/cs-utilities\" id=\"1884ccc62ad8f414\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19114\">Utilities</a></span>, <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/cs-banks\" id=\"1884ccc62b626a69\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19095\">Banking</a></span> and <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/cs-mining\" id=\"1884ccc62bc199e5\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"19107\">Mining</a></span> sectors led shares lower.</p><br/><p>At the close in Casablanca, the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/masi\" id=\"1884ccc62c31b962\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13228\">Moroccan All Shares</a></span> declined 2.45%.</p><br/><p>The best performers of the session on the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/masi\" id=\"1884ccc62c31b962\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13228\">Moroccan All Shares</a></span> were Miniere Touissit (CSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/miniere-touissit\" id=\"1884ccc62cf058c8\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13247\">CMT</a></span>), which rose 5.56% or 100.00 points to trade at 1,899.00 at the close. Meanwhile, Aradei Capital SA (CSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/aradei-capital\" id=\"1884ccc62d3cd6d8\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1168946\">ARD</a></span>) added 5.14% or 21.60 points to end at 441.60 and M2M Group (CSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/m2m-group\" id=\"1884ccc62d7a47bb\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13269\">M2M</a></span>) was up 5.11% or 23.00 points to 473.00 in late trade.</p><br/><p>The worst performers of the session were Delta Holding S.A (CSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/delta-holding\" id=\"1884ccc62da95b9e\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13253\">DHO</a></span>), which fell 9.64% or 8.00 points to trade at 75.00 at the close. LafargeHolcim Maroc (CSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/lafarge-ciments\" id=\"1884ccc62ddccadd\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13264\">LHM</a></span>) declined 6.13% or 111.00 points to end at 1,700.00 and Bmce Bank (CSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/bmce\" id=\"1884ccc62e09766d\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13242\">BOA</a></span>) was down 6.09% or 14.00 points to 216.00.</p><br/><p>Falling stocks outnumbered advancing ones on the Casablanca Stock Exchange by 33 to 26 and 3 ended unchanged.</p><br/><p>Shares in LafargeHolcim Maroc (CSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/lafarge-ciments\" id=\"1884ccc62ddccadd\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13264\">LHM</a></span>) fell to 52-week lows; falling 6.13% or 111.00 to 1,700.00.</p><br/><p>Crude oil for February delivery was down 0.87% or 0.51 to $57.84 a barrel. Elsewhere in commodities trading, Brent oil for delivery in February fell 1.01% or 0.63 to hit $61.61 a barrel, while the February Gold Futures contract rose 1.24% or 56.05 to trade at $4,558.85 a troy ounce.</p><br/><p>EUR/MAD was unchanged 0.00% to 10.76, while USD/MAD rose 0.22% to 9.12.</p><br/><p>The US Dollar Index Futures was down 0.10% at 97.58.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (6, 'Target shares gain as activist investor reportedly builds big stake', 'Investing.com', 'https://www.investing.com/news/stock-market-news/target-shares-gain-as-activist-investor-reportedly-builds-big-stake-4423152', '<img src=\"https://i-invdn-com.investing.com/news/moved_LYNXNPEI4H0GZ_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/target\" id=\"1884cc98b48ce9ab\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"8180\">Target</a></span> shares are gaining roughly 3.3% in early trading on Friday after the Financial Times reported that activist investor Toms Capital Investment Management has acquired a significant stake in the retail chain.</p><br/><p>The investment comes as <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Target</span></span> faces challenges following a prolonged sales slump that has erased nearly a third of its share value this year, the report added.</p><br/><p>&nbsp;<strong data-stringify-type=\"bold\">Get premium news and analysis by upgrading to InvestingPro</strong>&nbsp;-<strong data-stringify-type=\"bold\"><a href=\"https://www.investing.com/pro/pricing\" target=\"_blank\" rel=\"noopener noreferrer\" data-stringify-link=\"https://www.investing.com/pro/pricing\" data-sk=\"tooltip_parent\">&nbsp;get 55% off today</a></strong></p><br/><p>The retailer has struggled with 12 consecutive quarters of negative or negligible sales growth. Target’s stock has declined 64% from its pandemic-era peak, when consumers turned to the company as a one-stop destination for essentials, clothing, and home goods. The company has also underperformed compared to the broader retail sector.</p><br/><p>Toms Capital, founded in 2017 by former GLG Partners executives, has recently taken positions in several major companies including Pringles manufacturer <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/kellogg-co.\" id=\"1884cc98b4eb95d7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"8334\">Kellanova</a></span>, U.S. Steel, and <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Kenvue</span></span>, where it has advocated for strategic changes.</p><br/><p>The exact size of Toms Capital’s investment in Target remains undisclosed. Target had a market capitalization of about $43.7 billion as of Wednesday’s close.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (7, 'Nvidia’s Groq deal is confusing, ’hard time seeing the rational’ - analyst', 'Investing.com', 'https://www.investing.com/news/stock-market-news/nvidias-groq-deal-is-confusing-hard-time-seeing-the-rational--analyst-93CH-4423145', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEE141FU_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nvidia-corp\" id=\"1884cb39e2ae028e\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6497\">Nvidia</a></span> has on Wednesday entered into a non-exclusive inference technology licensing agreement with AI chip startup Groq, a deal that has left D.A. Davidson analyst Alex Platt puzzled about the strategic rationale.</p><br/><p>Platt expressed confusion in a note published Friday, questioning whether <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nvidia-corp\" id=\"1884cb39e2e3d740\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6497\">Nvidia’s</a></span> motivations were technological or defensive in nature.</p><br/><p>The analysts disputed claims that Groq has a technology advantage in today’s inference market. They pointed out that Groq’s current generation chip contains only 230MB of SRAM capacity, which they described as \"incredibly low\" compared to Nvidia’s HGX B300 with 288GB of HBM3E per-chip.</p><br/><p>This limited memory capacity restricts Groq’s technology to \"only a small subset of inference workloads,\" the analysts noted, making it unsuitable for the frontier models expected in the coming year that require terabytes of memory. \"<span style=\"color: rgb(51, 51, 51);\">we still have a hard time seeing the rationale,\" Platt said. </span></p><br/><p>Under the agreement, Nvidia will license Groq’s inference technology without exclusivity rights. Groq founder Jonathan Ross, President Sunny Madra, and other team members will join Nvidia, while Groq continues as an independent company under new CEO Simon Edwards.</p><br/><p>The deal could be worth up to $20 billion in cash, according to multiple news reports, though Nvidia is apparently not acquiring Groq itself or exclusive rights to its technology.</p><br/><p>DA Davidson analysts struggled to see the technological rationale, suggesting Groq’s chips might excel at prefill operations but noting that \"Nvidia already has Rubin CPX on the way.\" They also questioned whether this was a defensive move, stating that Nvidia \"only has to be concerned about Google for the foreseeable future.\"</p><br/><p>Despite their confusion, the analysts concluded they were \"inclined to give Jensen [Huang, Nvidia CEO] the benefit of the doubt\" regarding the strategic decision.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (8, 'ECD Automotive Design stock soars after 2026 product lineup expansion', 'Investing.com', 'https://www.investing.com/news/stock-market-news/ecd-automotive-design-stock-soars-after-2026-product-lineup-expansion-93CH-4423139', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEBAG0BO_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/ef-hutton-acquisition\" id=\"1884cabc8f9bdac2\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1198116\">ECD Automotive Design Inc (NASDAQ:ECDA)</a></span> stock surged 68.2% on Friday after the Florida-based luxury vehicle manufacturer announced a major expansion of its product lineup for 2026.</p><br/><p>The company, known for re-engineering iconic automobiles, revealed plans to broaden its offerings across heritage-inspired sports coupes, classic SUVs, and modern lifestyle 4x4s. The expansion includes new model families based on BMW, Jaguar, Porsche, and Mustang platforms in its Boutique division.</p><br/><p>ECD is restructuring its classic SUV lineup into two distinct divisions—Heritage and Custom—each with dedicated production assembly lines. The Heritage Line will focus on period-correct restorations with essential modern upgrades, while the Custom Line will support more advanced, highly personalized builds.</p><br/><p>The company also plans to introduce a new American classic SUV platform and implement a safety and convenience modernization initiative across both divisions, adding features such as anti-lock braking systems, global remote locking, and power-assisted tailgates.</p><br/><p>Additionally, ECD is expanding its modern lineup through the Chelsea Truck Company USA brand, with custom programs built on platforms including the new Land Rover Defender, Ineos Grenadier, Range Rover models, Jeep, Mercedes-Benz G-Wagen, and Toyota Land Cruiser.</p><br/><p>\"2026 represents a breakthrough year for ECD’s product development,\" said Scott Wallace, CEO. \"From expanded heritage programs to modern SUV platforms and new safety innovations for classic vehicles, we’re building the most comprehensive and forward-thinking portfolio in our history—while staying true to the character of the icons our clients love.\"</p><br/><p>To support the expanded product range, the company has introduced upgraded engineering and design systems, including modular build architectures and improved electrical frameworks.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (9, 'Wall St little changed in post-Christmas session', 'Reuters', 'https://www.investing.com/news/stock-market-news/wall-st-little-changed-in-postchristmas-session-4423137', '<img src=\"https://i-invdn-com.investing.com/trkd-images/LYNXMPELBP0DZ_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p></p><br/><p>Dec 26 (Reuters) - Wall Street indexes opened nearly flat in light post-Christmas trading on Friday, while investors bet that more interest rate cuts and strong corporate earnings would propel markets to fresh highs next year.</p><br/><p>At 09:30 a.m. ET, the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/us-30\" id=\"1884caafe9abaebf\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"169\">Dow Jones Industrial Average</a></span> fell 7.15 points, or 0.01%, to 48,724.01. The S&amp;P 500 gained 6.25 points, or 0.09%, to 6,938.30, and the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/nasdaq-composite\" id=\"1884caafea5832b5\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"14958\">Nasdaq Composite</a></span> rose 32.06 points, or 0.10%, to 23,645.37.</p><br/><p></p><br/><p></p><br/><p></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (10, 'U.S. stocks open flat in thin post-Christmas trade', 'Investing.com', 'https://www.investing.com/news/stock-market-news/wall-st-futures-tick-higher-in-thin-postchristmas-trade-4422911', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEBAI0NN_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com-- U.S. stocks were mostly unchanged after the Christmas holiday with activity subdued and volumes expected to remain thin ahead of a truncated New Year’s week.</p><br/><p dir=\"ltr\">At 09:31 ET (14:31 GMT), <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/us-spx-500\" id=\"1884ca7cb0ca096c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"166\">S&amp;P 500</a></span> was mostly flat at 6,933.25 points, while <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/nasdaq-composite\" id=\"1884ca7cb14c0e44\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"14958\">NASDAQ Composite</a></span> was unchanged at 23,613.25 points. <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/us-30\" id=\"1884ca7cb17990cd\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"169\">Dow Jones Industrial Average</a></span> was down 27 points to 48,706 points.</p><br/><p dir=\"ltr\"></p><br/><p dir=\"ltr\"></p><br/><p>U.S. equity markets were closed on Thursday for Christmas Day, following an early close on Wednesday, resulting in&nbsp;lower trading volumes&nbsp;which contributed to muted futures moves.</p><br/><p>With many institutional desks lightly staffed and key markets in Europe and Asia observing holidays, participants cited thin liquidity as a factor keeping futures in a narrow range.</p><br/><p>Earlier this week, the S&amp;P 500&nbsp;hit a fresh record closing high&nbsp;amid better AI optimism and strong third-quarter U.S. economic growth that exceeded expectations and buoyed sentiment toward extended expansion.</p><br/><p>\"Tech sentiment improved markedly&nbsp;over the last 1.5 weeks thanks to&nbsp;<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/micron-tech\" id=\"1884ca7cb1b84972\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"8092\">Micron’s</a></span> blow-out report/guide&nbsp;and media reports about a&nbsp;~$100B OpenAI capital raise,\" Vital Knowledge analyst Adam Crisafulli said.</p><br/><p>Growth in gross domestic product was reported at an annualized 4.3%, the fastest pace in two years, supporting expectations that the broader economy remains resilient.</p><br/><p>Additionally, renewed enthusiasm for technology and AI-related stocks, coupled with market speculation on eventual Federal Reserve interest rate cuts in 2026, underpinned the advance.</p><br/><p>With markets poised to resume full trading on Friday after the holiday, investors will monitor economic data and positioning into year-end while navigating historically light volumes and a potential seasonal “Santa Claus rally” that often characterizes late-December trading.</p><br/><p><em>(Ayushman Ojha contributed to this report.)</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (11, 'Breaking down Nvidia’s unusual $20 billion deal with Groq', 'Investing.com', 'https://www.investing.com/news/stock-market-news/nvidia-to-acquire-groq-for-20-billion-in-its-largest-deal-ever-cnbc-reports-4422745', '<img src=\"https://i-invdn-com.investing.com/news/moved_LYNXMPEL4L0QK_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p data-start=\"0\" data-end=\"243\">Investing.com -- Reports emerged on Wednesday that <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nvidia-corp\" id=\"1884ca38a3b9cf9c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6497\">NVIDIA (NASDAQ:NVDA)</a></span> has agreed to acquire Groq, a designer of high-performance artificial intelligence accelerator chips, in a $20 billion all-cash deal.&nbsp;Groq recently raised $750 million at a valuation of about $6.9 billion.&nbsp;</p><br/><p data-start=\"0\" data-end=\"243\"></p><br/><p data-start=\"0\" data-end=\"243\">]]</p><br/><p data-start=\"0\" data-end=\"236\">However, the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nvidia-corp\" id=\"1884ca38a3f933e4\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6497\">Nvidia</a></span>–Groq transaction does not appear to be a traditional acquisition despite CNBC reporting. Groq said it has entered into a \"non-exclusive inference technology licensing agreement\" with Nvidia aimed at accelerating AI inference at global scale.</p><br/><p data-start=\"238\" data-end=\"454\">Under the terms of the agreement, Nvidia will license Groq’s inference technology, reflecting what Groq described as a shared focus on expanding access to high-performance, low-cost inference. The deal does not grant exclusivity.</p><br/><p data-start=\"456\" data-end=\"771\">As part of the arrangement, Groq founder Jonathan Ross, President Sunny Madra and other members of the Groq team will join Nvidia to help advance and scale the licensed technology. Groq said it will continue to operate as an independent company, with Simon Edwards stepping into the role of chief executive officer.</p><br/><p data-start=\"773\" data-end=\"991\" data-is-last-node=\"\" data-is-only-node=\"\">That structure suggests Nvidia is not acquiring Groq itself, its intellectual property, or exclusive rights to its technology, but is instead paying for licensed use of the technology and the addition of key personnel. Nvidia is yet to comment on the deal.</p><br/><p data-start=\"773\" data-end=\"991\" data-is-last-node=\"\" data-is-only-node=\"\">Shares in the AI chipmaking behemoth are up 0.7% in thin premarket trade Friday.</p><br/><p data-start=\"595\" data-end=\"789\">Groq was founded by former engineers behind Google’s tensor processing unit, or TPU, a chip designed to compete with Nvidia in artificial intelligence workloads.</p><br/><p data-start=\"773\" data-end=\"991\" data-is-last-node=\"\" data-is-only-node=\"\">Bank of America analyst Vivek Arya said that the deal \"implies NVDA recognition that while GPU dominated AI training, the rapid shift towards inference could require more specialized chips.\"</p><br/><p data-start=\"773\" data-end=\"991\" data-is-last-node=\"\" data-is-only-node=\"\">Arya describes <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nvidia-corp\" id=\"1884ca38a44d6ede\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6497\">Nvidia’s</a></span> GPUs as general-purpose platforms while Groq’s LPUs are positioned as \"specialized,\" ASIC-like chips optimized for fast and highly predictable AI inference.</p><br/><p data-start=\"773\" data-end=\"991\" data-is-last-node=\"\" data-is-only-node=\"\">The LPUs rely on large amounts of on-chip SRAM to store model weights and working data, enabling extremely fast per-token access, but with more limited scalability compared with Nvidia’s GPU platforms that use high-bandwidth memory to maximize throughput, the analyst explained.</p><br/><p data-start=\"773\" data-end=\"991\" data-is-last-node=\"\" data-is-only-node=\"\">Arya envisions future Nvidia systems where GPUs and LPUs coexist within the same rack, connected via NVLink.</p><br/><p data-start=\"773\" data-end=\"991\" data-is-last-node=\"\" data-is-only-node=\"\">\"Longer-term we think the potential Groq deal could be strategic, similar to NVDA’s Apr’20 Mellanox acquisition that is now the foundation of NVDA’s networking/AI scaling moat,\" he concluded.</p><br/><p data-start=\"595\" data-end=\"789\">Baird analyst Tristan Gerra said that while he believes that Nvidia’s GPUs \"will retain the majority of the AI processor market by 2030, custom ASIC could be accretive to Nvidia’s TAM over time.\"</p><br/><p data-start=\"595\" data-end=\"789\">Similarly, Bernstein analyst Stacy Rasgon commented that \"$20B seems expensive for a licensing deal,\" especially for a “non-exclusive” agreement. However, he notes that the money invoived \"is still pocket change for NVDA given their current $61B cash balance (and massive future free cash flow) and $4.6T market capitalization (it’s about 82 cents per share).\"</p><br/><p data-start=\"595\" data-end=\"789\">\"We’re inclined to give them the benefit of the doubt,\" Rasgon wrote.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (12, 'Can Fite Biopharma stock soars on Brazil patent grant for sexual dysfunction', 'Investing.com', 'https://www.investing.com/news/stock-market-news/can-fite-biopharma-stock-soars-on-brazil-patent-grant-for-sexual-dysfunction-93CH-4423122', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEA7H0NX_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/can-fite-biopharma-ltd\" id=\"1884ca2ed793d484\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"949575\">Can-Fite BioPharma Ltd. (NYSE American:CANF)</a></span> stock surged 47% in premarket trading Friday after the company announced that Brazil’s patent office granted protection for its A3 adenosine receptor agonists in treating sexual dysfunction.</p><br/><p>The Brazilian Patent Office (INPI) issued Patent No. BR112015002697-4, titled \"Use of an A3 Adenosine Receptor Agonist for the Treatment of Sexual Dysfunction,\" strengthening Can-Fite’s intellectual property portfolio in Latin America’s largest pharmaceutical market.</p><br/><p>The biotechnology company, which develops small-molecule drugs targeting oncological and inflammatory diseases, noted that sexual dysfunction is associated with vascular, inflammatory, and metabolic pathways. Can-Fite’s preclinical and clinical data suggest that A3 adenosine receptor activation may modulate key signaling mechanisms involved in erectile and sexual function.</p><br/><p>\"The grant of this Brazilian patent further validates the therapeutic versatility of A3 adenosine receptor agonists and expands our intellectual-property footprint in a major pharmaceutical market,\" said Pnina Fishman, Ph.D., Chairperson and Chief Scientific Officer of Can-Fite BioPharma.</p><br/><p>The company continues to advance its A3AR agonist platform across multiple indications, including oncology, inflammatory diseases, and other non-oncologic conditions, while evaluating strategic opportunities to maximize the value of its patent estate.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (13, 'Warner Bros. Discovery shares fall on Paramount Skydance dispute', 'Investing.com', 'https://www.investing.com/news/stock-market-news/warner-bros-discovery-shares-fall-on-paramount-skydance-dispute-93CH-4423121', '<img src=\"https://i-invdn-com.investing.com/news/netflix_800x533_L_1412585537.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/discovery-holding-co\" id=\"1884ca265ca29429\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6382\">Warner Bros. Discovery</a></span> shares slipped 2.2% in premarket trading Friday following a New York Post report that Paramount Skydance might abandon its $30-per-share cash bid and pursue legal action against the company’s board.</p><br/><p>According to the report, sources within Paramount Skydance claim that Warner Bros. Discovery directors and management disregarded their sixth all-cash offer, instead showing preference for <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/netflix,-inc.\" id=\"1884ca265cd61249\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13063\">Netflix</a></span>’s cash-stock bid throughout the negotiation process.</p><br/><p>The report suggests this favoritism stemmed from a personal relationship between Warner Bros. Discovery Chief Executive David Zaslav and <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Netflix</span></span> CEO Ted Sarandos.</p><br/><p>Paramount Skydance is now considering litigation against the Warner Bros. Discovery board over how the bidding process was handled, the New York Post reported.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (14, 'TSMC honors 30 suppliers with 2025 awards, ULVAC, Advantest, Canon and Ebara included', 'Investing.com', 'https://www.investing.com/news/stock-market-news/tsmc-honors-30-suppliers-with-2025-awards-ulvac-advantest-canon-and-ebara-included-93CH-4423120', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEBAG0BO_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/ulvac-inc\" id=\"1884c9e9960abae7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"946219\">ULVAC</a></span>, <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/advantest-corp.\" id=\"1884c9e996433130\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44296\">Advantest</a></span>, <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/canon-inc.\" id=\"1884c9e99677c0a6\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44187\">Canon</a></span> and <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/ebara-corp.\" id=\"1884c9e996a5fcb7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44171\">Ebara</a></span> announced on Tuesday and Wednesday that they had received 2025 supplier awards from <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/taiwan-semicond.manufacturing-co\" id=\"1884c9e996dad371\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"32306\">Taiwan Semiconductor Manufacturing Company (NYSE:TSM)</a></span>.</p><br/><p>TSMC officially announced these awards on November 26, but it appears there were restrictions on when and how recipients could disclose this information.</p><br/><p>A total of 30 companies received recognition from the semiconductor manufacturing giant. Among Japanese equipment manufacturers, SCREEN Holdings, Disco, and <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/kokusai-electric\" id=\"1884c9e99709b4c5\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1207905\">Kokusai Electric</a></span> were also honored with awards.</p><br/><p><span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/tokyo-electron-ltd.\" id=\"1884c9e99738bdf2\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44237\">Tokyo Electron</a></span>, which had previously received the most awards since 2021 with four recognitions, was notably absent from this year’s list of recipients.</p><br/><p>For Advantest and Ebara, this marks their first time receiving a supplier award from TSMC.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (15, 'Thursday’s Insider Activity: Quiet Day before Christmas Weekend', 'Investing.com', 'https://www.investing.com/news/stock-market-news/thursdays-insider-activity-quiet-day-before-christmas-weekend-93CH-4423113', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEB0E0CQ_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Here’s a summary of the insider trading activities disclosed on Thursday, December 25, 2025.</p><br/><p>Top Insider Buys:</p><br/><p>No significant insider purchases were reported for Thursday.</p><br/><p>Top Insider Sells:</p><br/><p>No significant insider sales were reported for Thursday.</p><br/><p>Insider trading activity appears to have been minimal ahead of the Christmas holiday weekend. This is not unusual as trading volumes and corporate disclosures typically decrease during major holidays.</p><br/><p>Why Monitor Insider Transactions?</p><br/><p>Tracking insider buying and selling can provide valuable insights for investors. When corporate executives, board members, and major shareholders purchase company stock with their own money, it may signal confidence in the company’s future prospects. Conversely, insider selling might raise questions, though it often occurs for personal reasons such as diversification or tax planning. While insider transactions shouldn’t be the sole basis for investment decisions, they represent one piece of the puzzle that can help inform your overall market strategy. Always consider insider activity alongside other fundamental and technical factors when evaluating potential investments.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (16, 'Celularity stock drops after CMS withdraws skin substitute LCDs', 'Investing.com', 'https://www.investing.com/news/stock-market-news/celularity-stock-drops-after-cms-withdraws-skin-substitute-lcds-93CH-4423112', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEB9606Q_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/gx-acquisition\" id=\"1884c875f5f7bde4\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1163751\">Celularity Inc (NASDAQ:CELU)</a></span> stock dropped 2.8% in premarket trading Friday after the Centers for Medicare &amp; Medicaid Services (CMS) withdrew Local Coverage Determinations (LCDs) for skin substitutes that were set to take effect January 1, 2026.</p><br/><p>The withdrawn LCDs had previously maintained Medicare coverage eligibility for <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Celularity</span></span>’s Biovance® and Biovance 3L products while eliminating coverage for 158 skin substitute products from other companies. Despite the withdrawal, CMS’s new payment policy setting skin substitute reimbursement at a flat $127.28 per square centimeter remains in effect.</p><br/><p>Celularity CEO Dr. Robert J. Hariri commented on the development, noting that the company has \"amassed substantial real-world evidence\" demonstrating the effectiveness of its Biovance® Human Amniotic Membrane Allograft for wound healing in diverse patient populations.</p><br/><p>Dr. Hariri emphasized that Celularity’s manufacturing process, established since the commercial launch of Biovance® in April 2014, allows the company to \"operate comfortably under the new Medicare reimbursement for skin substitute products.\"</p><br/><p>The regenerative medicine company, which focuses on addressing age-related and degenerative diseases, maintains a GMP/GTP manufacturing facility in Florham Park, New Jersey, where it produces commercial biomaterial products and investigational cell therapy products.</p><br/><p>The stock movement suggests investors are reassessing the impact of the regulatory change on Celularity’s competitive position in the skin substitute market heading into 2026.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (17, '374Water stock rises on PFAS destruction project partnership', 'Investing.com', 'https://www.investing.com/news/stock-market-news/374water-stock-rises-on-pfas-destruction-project-partnership-93CH-4423111', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEB280W7_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/374water-otc\" id=\"1884c830e4323a67\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1192308\">374Water Inc (NASDAQ:SCWO)</a></span> stock rose 2.1% in premarket trading Friday after the company announced a partnership to destroy biosolids containing harmful \"forever chemicals.\"</p><br/><p>The waste destruction technology provider will work with The Cedar Rapids Water Control Pollution Facility and environmental consultancy Brown and Caldwell on a project targeting per- and polyfluoroalkyl substances (PFAS) in biosolids. The project is expected to begin in early Q1 2026, with results anticipated by late Q1 or early Q2.</p><br/><p>PFAS are persistent man-made chemicals that accumulate in water, soil, and wastewater systems. Their increasing presence in municipal biosolids has prompted Cedar Rapids to seek solutions for destroying PFAS-contaminated waste streams.</p><br/><p>\"<span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">374Water</span></span> is an ideal partner to enable meaningful action against PFAS contamination at the City of Cedar Rapids’ advanced wastewater treatment facility,\" said Stephen J. Jones, Chairman and Interim President and CEO of 374Water. \"Our AirSCWO technology has demonstrated the effectiveness, scalability, and versatility of our solutions to destroy solid and liquid wastes.\"</p><br/><p>The company’s technology aims to help Cedar Rapids mitigate PFAS contamination while establishing new standards for responsible waste management across the country.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (18, 'Adicet Bio stock falls after announcing 1-for-16 reverse split', 'Investing.com', 'https://www.investing.com/news/stock-market-news/adicet-bio-stock-falls-after-announcing-1for16-reverse-split-93CH-4423108', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEA7D094_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/restorbio\" id=\"1884c806a729fcb7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1061143\">Adicet Bio Inc (NASDAQ:ACET)</a></span> stock fell 9.2% in premarket trading Friday after the clinical-stage biotechnology company announced a 1-for-16 reverse stock split to regain compliance with Nasdaq’s minimum bid price requirement.</p><br/><p>The reverse split will take effect at 12:01 a.m. Eastern Time on December 30, 2025, with the stock beginning to trade on a split-adjusted basis when markets open that day. The move will reduce Adicet’s outstanding shares from approximately 153.3 million to about 9.6 million.</p><br/><p>While the total authorized shares will remain at 300 million, the split will increase the number of shares available for future issuance. The company’s board approved the split ratio, which falls within the range previously authorized by stockholders at the Special Meeting held on December 19, 2025.</p><br/><p>Proportional adjustments will be made to stock options, equity awards, and pre-funded warrants. No fractional shares will be issued, with stockholders entitled to receive cash in lieu of any fractional shares resulting from the split.</p><br/><p><span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Adicet Bio</span></span> focuses on discovering and developing allogeneic gamma delta T cell therapies for autoimmune diseases and cancer. The reverse split is specifically designed to help the company meet Nasdaq’s continued listing requirements.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (19, 'Sobr Safe stock falls after announcing $2 million private placement', 'Investing.com', 'https://www.investing.com/news/stock-market-news/sobr-safe-stock-falls-after-announcing-2-million-private-placement-93CH-4423105', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEC0E0NG_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/sobr-safe\" id=\"1884c7a8e30be4fd\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1190456\">Sobr Safe Inc (NASDAQ:SOBR)</a></span> stock tumbled 11.4% in premarket trading Friday, retreating after the alcohol monitoring technology company announced a private placement to raise approximately $2 million.</p><br/><p>The company said it has entered into definitive agreements to sell 1,290,324 shares of common stock (or pre-funded warrants) along with Series C and Series D warrants at a purchase price of $1.55 per share. The warrants will have an exercise price of $1.30 per share and will be exercisable immediately upon issuance.</p><br/><p>H.C. Wainwright &amp; Co. is acting as the exclusive placement agent for the offering, which is expected to close around December 29, 2025. <span itemscope itemtype=\"http://schema.org/Corporation\"><span itemprop=\"name\">Sobr Safe</span></span> intends to use the net proceeds for working capital and general corporate purposes.</p><br/><p>The Series C warrants will expire five years after the effective date of the resale registration statement, while the Series D warrants will expire after 24 months.</p><br/><p>Friday’s premarket decline follows a significant 82.3% surge in Sobr Safe’s stock during trading hours on December 24, 2025, when the private placement was announced, suggesting the current movement may represent a slight correction after the initial rally.</p><br/><p>Sobr Safe describes itself as \"the leader in next-generation alcohol monitoring and detection technology\" and trades on the Nasdaq under the ticker SOBR.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (20, 'Sidus Space stock soars after closing $25 million public offering', 'Investing.com', 'https://www.investing.com/news/stock-market-news/sidus-space-stock-soars-after-closing-25-million-public-offering-93CH-4423099', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEC0Q1B5_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- Sidus Space Inc (NASDAQ:SIDU) stock surged 33.2% in Friday’s premarket trading after the space and defense technology company announced the closing of its previously announced public offering.</p><br/><p>The company raised approximately $25 million in gross proceeds through a best-efforts public offering of 19,230,800 shares of its Class A common stock. Each share was sold at a public offering price of $1.30.</p><br/><p>Sidus Space plans to use the net proceeds for several key initiatives including sales and marketing, operational costs, product development, manufacturing expansion, and general working capital purposes.</p><br/><p>ThinkEquity acted as the sole placement agent for the offering, which was previously announced by the company. All of the Class A common stock shares in the offering were provided by Sidus Space.</p><br/><p>The significant stock price jump reflects positive market reaction to the successful capital raise, which strengthens the company’s financial position as it continues to develop its space and defense technology offerings.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (21, 'Arcadia Biosciences stock rises after Roosevelt terminates merger deal', 'Investing.com', 'https://www.investing.com/news/stock-market-news/arcadia-biosciences-stock-rises-after-roosevelt-terminates-merger-deal-93CH-4423094', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEA7H0NX_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/arcadia-biosciences\" id=\"1884c72832312fad\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"953050\">Arcadia Biosciences Inc (NASDAQ:RKDA)</a></span> stock rose 9% in premarket trading after the company announced that Roosevelt Resources, LP has terminated their Securities Exchange Agreement dated December 4, 2024.</p><br/><p>The agreement, which had outlined a proposed business combination between the two companies, was terminated by Roosevelt on December 24, 2025, according to the terms of the agreement.</p><br/><p>Following this development, Arcadia CEO T.J. Schaefer stated that the company will \"resume the process of evaluating strategic alternatives in order to create value for our shareholders.\"</p><br/><p>Schaefer highlighted the company’s operational achievements over the past two-and-a-half years, including streamlining operations, reducing operating expenses, and growing the Zola coconut water brand without taking on long-term debt.</p><br/><p>The wellness products company noted that it continues to hold approximately 2.7 million shares of <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/bite-acquisition\" id=\"1884c728326bde16\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1176130\">Above Food Ingredients Inc.</a></span> common stock and believes it is entitled to additional consideration related to its May 2024 sale of GoodWheat.</p><br/><p>Arcadia’s management expressed confidence that these assets, combined with its Nasdaq listing and Zola business, make the company an attractive candidate for future strategic transactions.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (22, 'Aptevo Therapeutics stock tumbles after announcing 1-for-18 reverse split', 'Investing.com', 'https://www.investing.com/news/stock-market-news/aptevo-therapeutics-stock-tumbles-after-announcing-1for18-reverse-split-93CH-4423092', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEAB20I9_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/aptevo-therapeutics-inc\" id=\"1884c6f80b2759bc\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"985950\">Aptevo Therapeutics Inc. (NASDAQ:APVO)</a></span> stock plunged 30.9% in premarket trading Friday after the clinical-stage biotechnology company announced plans for a 1-for-18 reverse stock split.</p><br/><p>The reverse split is expected to take effect on December 29 at 5:01 p.m. Eastern Time, with shares beginning to trade on a split-adjusted basis when markets open on December 30. The move will reduce Aptevo’s outstanding common stock from approximately 18 million shares to about 1 million shares.</p><br/><p>Aptevo’s stockholders approved the reverse split at the company’s Annual Meeting on July 24, giving the Board discretion to determine the final ratio. The Board approved the 1-for-18 ratio on December 17.</p><br/><p>The company, which focuses on developing novel immune-oncology therapeutics based on its proprietary ADAPTIR and ADAPTIR-FLEX platform technologies, will maintain its \"APVO\" trading symbol on the Nasdaq Capital Market following the split.</p><br/><p>The reverse split will affect all outstanding shares of common stock as well as outstanding options, restricted stock units, warrants, and other securities. The number of shares available under the company’s equity incentive plans will also be adjusted accordingly. No fractional shares will be issued, with affected stockholders receiving cash payments instead.</p><br/><p>The authorized number of shares of common stock and preferred stock will remain unchanged, while the par value will stay at $0.001 per share.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (23, 'Top Fintech Stocks to Watch in 2026 as Tokenization and AI Transform Finance', 'Investing.com', 'https://www.investing.com/news/stock-market-news/top-fintech-stocks-to-watch-in-2026-as-tokenization-and-ai-transform-finance-93CH-4423065', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEB9M0BY_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- As the financial technology landscape evolves with tokenization, AI advancements, and market structure modernization, several companies are positioned to capitalize on these trends in 2026. According to Clear Street’s analysis, these top fintech stocks are poised to benefit from regulatory clarity, technological innovation, and changing market dynamics.</p><br/><p>The fintech sector is experiencing several key transformations that will shape investment opportunities in 2026. Tokenization is shifting trading and payment activities toward 24/7 availability with more transparent and automated rails. AI is simultaneously boosting productivity while creating new fraud risks, driving demand for advanced RegTech solutions. Meanwhile, agentic AI is enabling automated shopping experiences, the IPO market is showing signs of recovery after a prolonged drought, and the Fed’s continued rate cut path is expected to stimulate loan origination and consumer spending.</p><br/><p><strong>Get premium news and analyis by upgrading to InvestingPro - </strong><a rel=\"noopener noreferrer\" href=\"https://www.investing.com/pro/pricing?referral=inv_in_article_anchor\" target=\"_blank\"><strong>get 55% off today</strong></a></p><br/><p><strong>1. Nasdaq</strong></p><br/><p>Clear Street rates Nasdaq as a Buy with a $108 price target. The company is viewed as an underappreciated tech partner with growing recurring, non-trading revenue streams that support durable earnings growth. Four key tailwinds support Nasdaq in 2026: increasing RegTech demand as AI elevates fraud risk, an IPO recovery that could lift sentiment, extended trading hours leveraging tokenization, and continued growth in passive investing. With passive AUM projected to grow from $30 trillion in 2024 to $48 trillion by 2029, Nasdaq’s index licensing and data services are well-positioned to benefit. Ongoing deleveraging should also translate into higher capital returns and improved market valuation.</p><br/><p>In a recent development, Morgan Stanley upgraded Nasdaq to Overweight from Equalweight, citing expectations for accelerated revenue growth. The company also announced cash tender offers for its outstanding senior notes, later increasing the purchase caps for two series.</p><br/><p><strong>2. Coinbase Global</strong></p><br/><p>Clear Street assigns Coinbase a Buy rating with a $415 price target. Coinbase represents the best large-cap exposure to sustained blockchain adoption, operating at the intersection of trading, custody, stablecoin economics, and emerging on-chain use cases. Regulatory clarity is expected to be a major re-rating catalyst, potentially broadening the investable universe and accelerating institutional participation. The company’s revenue base has become more diversified than in previous cycles, with growing contributions from subscription services and stablecoin economics, which helps smooth cyclicality and supports higher margins. Despite participating meaningfully in USDC economics, Coinbase trades at a discount to Circle (15.7x vs. 28.0x 2026E EV/EBITDA).</p><br/><p>Coinbase recently unveiled a new suite of products, including commission-free trading and a robo-advisor service, as it aims to become an \"Everything Exchange.\" Following the announcement, analyst ratings were mixed, with Cantor Fitzgerald reiterating an Overweight rating while Mizuho and Goldman Sachs maintained Neutral ratings on the company.</p><br/><p><strong>3. S&amp;P Global</strong></p><br/><p>Clear Street rates S&amp;P Global as a Buy with a $587 price target. The company’s outlook improves heading into 2026 with several catalysts: an easing rate environment supporting debt issuance and ratings activity, re-acceleration in Market Intelligence growth, and the planned Mobility separation scheduled for April-September 2026. The separation is expected to reduce complexity and clarify the valuation of the remaining information services platform. S&amp;P Global’s relative valuation appears attractive compared to Moody’s, trading at 26.5x 2026E PE versus 31.6x for MCO, creating room for re-rating as these catalysts materialize.</p><br/><p>S&amp;P Global announced a strategic partnership with Google Cloud to advance its AI capabilities and has appointed several key executives, including a new CFO, for its Mobility business ahead of its planned separation into a standalone company.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (24, 'S&P 500 eyes 7,000 mark as investors look for upbeat end to strong 2025', 'Reuters', 'https://www.investing.com/news/stock-market-news/sp-500-eyes-7000-mark-as-investors-look-for-upbeat-end-to-strong-2025-4423045', '<img src=\"https://i-invdn-com.investing.com/trkd-images/LYNXMPELBP0AL_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>NEW YORK, Dec 26 (Reuters) - Investors are looking for the U.S. stock market to end 2025 on a high note next week, with equities at record peaks and nearing further bullish milestones to close out another strong year.</p><br/><p>Major U.S. indexes were on course to end December higher after stocks shook off turbulence earlier in the month driven by weakness in technology shares over worries tied to spending on artificial intelligence.&nbsp;</p><br/><p>The S&amp;P 500 posted a record close on Wednesday, ahead of the Christmas holiday on Thursday, and was about 1% from reaching the 7,000 level for the first time. The benchmark index was on track for its eighth straight month of gains, which would be its longest monthly winning streak since 2017-2018.</p><br/><p>\"Momentum is certainly on the side of the bulls,\" said Paul Nolte, senior wealth adviser and market strategist at Murphy &amp; Sylvest Wealth Management. \"Barring any exogenous event, the path of least resistance for stocks, I think, is higher.\"</p><br/><p>Minutes from the Federal Reserve’s most recent meeting highlight the market events in the holiday-shortened week ahead, while year-end portfolio adjustments could cause some volatility at a time when light trading volumes can exaggerate asset price moves.</p><br/><p>Heading into the new year, investors are highly focused on when the Fed might further cut interest rates. The U.S. central bank, which balances goals of contained inflation and full employment, lowered its benchmark rate by 75 basis points over its last three meetings of 2025 to the current level of 3.50%-3.75%.</p><br/><p>But the Fed’s most recent vote at its December 9-10 meeting to lower rates by a quarter percentage point was divided, while policymakers also gave widely different projections about rates in the coming year. The minutes for that meeting, due to be released on Tuesday of next week, may be \"illuminating to hear what some of the arguments were around the table,\" said Michael Reynolds, vice president of investment strategy at Glenmede.</p><br/><p>\"Handicapping how many rate cuts we’re going to get next year is a big thing markets are focused on right now,\" Reynolds said. \"We’ll just get a little bit more information on that next week.\"</p><br/><p>Investors are also waiting for President Donald Trump to nominate a Fed chair to replace Jerome Powell, whose term ends in May, and any inkling of Trump’s decision could sway markets in the coming week.</p><br/><p>With just a handful of trading sessions left in 2025, the S&amp;P 500 was up nearly 18% for the year, with the technology-heavy <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/nasdaq-composite\" id=\"1884bf3d94b3dd25\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"14958\">Nasdaq Composite</a></span> up 22%.&nbsp;</p><br/><p>However, the tech sector, which has been the main driver of the more than three-year-old bull market, has struggled in recent weeks, while other areas of the market have shined. Despite rebounding this week, the S&amp;P 500 tech sector has declined more than 3% since the start of November. Over that time, areas such as financials, transports, healthcare and small caps have posted solid gains.</p><br/><p></p><br/><p>The market moves indicate some rotation into areas where valuations are more moderate, said Anthony Saglimbene, chief market strategist at Ameriprise Financial.</p><br/><p>\"There are more investors that are buying in to the narrative that the economy is on pretty solid footing right now,\"&nbsp; Saglimbene said. \"And it has weathered a lot of potential roadblocks this year that might not be such roadblocks next year.\"</p><br/><p></p><br/><p></p><br/><p></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (25, 'India stocks lower at close of trade; Nifty 50 down 0.38%', 'Investing.com', 'https://www.investing.com/news/stock-market-news/india-stocks-lower-at-close-of-trade-nifty-50-down-038-4423034', '<img src=\"https://i-invdn-com.investing.com/news/MumbaiStockExchange_800x533_L_1628748294.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com – India stocks were lower after the close on Friday, as losses in the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/s-p-bse-teck\" id=\"1884bd391243947e\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39950\">Technology</a></span>, <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/s-p-bse-fast-moving-consumer-goods\" id=\"1884bd3912910d92\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39941\">Fast Moving Consumer Goods</a></span> and <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/s-p-bse-healthcare\" id=\"1884bd3912d19a2c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39942\">Healthcare</a></span> sectors led shares lower.</p><br/><p>At the close in NSE, the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/s-p-cnx-nifty\" id=\"1884bd39130f528a\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"17940\">Nifty 50</a></span> lost 0.38%, while the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/sensex\" id=\"1884bd3913643ac2\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39929\">BSE Sensex 30</a></span> index declined 0.43%.</p><br/><p>The best performers of the session on the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/s-p-cnx-nifty\" id=\"1884bd39130f528a\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"17940\">Nifty 50</a></span> were Titan Company Ltd (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/titan-industries\" id=\"1884bd3913eaa06c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"18433\">TITN</a></span>), which rose 2.19% or 85.70 points to trade at 3,995.00 at the close. Meanwhile, Hindalco Industries Ltd. (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/hindalco-industries\" id=\"1884bd39141b6b17\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"18187\">HALC</a></span>) added 0.99% or 8.55 points to end at 873.00 and Nestle India Ltd (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nestle\" id=\"1884bd39144e8fc8\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"30059\">NEST</a></span>) was up 0.82% or 10.30 points to 1,270.00 in late trade.</p><br/><p>The worst performers of the session were Asian Paints Ltd. (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/asian-paints\" id=\"1884bd39147592da\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"18011\">ASPN</a></span>), which fell 1.40% or 38.90 points to trade at 2,746.60 at the close. Shriram Finance Ltd. (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/shriram-transport-finance\" id=\"1884bd3914a824cf\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"18386\">SHMF</a></span>) declined 1.37% or 13.30 points to end at 960.40 and Tata Consultancy Services Ltd. (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/tata-consultancy-services\" id=\"1884bd3914c6d0b7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"18420\">TCS</a></span>) was down 1.27% or 42.10 points to 3,276.90.</p><br/><p>The top performers on the BSE Sensex 30 were Titan Company Ltd (BO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/titan-industries?cid=18433\" id=\"1884bd3915026551\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39709\">TITN</a></span>) which rose 2.19% to 3,994.00, Nestle India Ltd (BO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nestle?cid=30059\" id=\"1884bd3915390766\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39745\">NEST</a></span>) which was up 0.76% to settle at 1,268.40 and NTPC Ltd (BO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/ntpc?cid=18297\" id=\"1884bd391575ffef\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39602\">NTPC</a></span>) which gained 0.59% to close at 324.50.</p><br/><p>The worst performers were Bajaj Finance Ltd (BO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/bajaj-finance?cid=18022\" id=\"1884bd39159d72dd\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39382\">BJFN</a></span>) which was down 1.52% to 999.45 in late trade, Asian Paints Ltd. (BO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/asian-paints?cid=18011\" id=\"1884bd3915cc2157\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39373\">ASPN</a></span>) which lost 1.42% to settle at 2,746.00 and HCL Technologies Ltd (BO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/hcl-technologies?cid=18176\" id=\"1884bd3915fc117c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39505\">HCLT</a></span>) which was down 1.36% to 1,652.15 at the close.</p><br/><p>Falling stocks outnumbered advancing ones on the India National Stock Exchange by 1514 to 976 and 48 ended unchanged; on the Bombay Stock Exchange, 2301 fell and 1683 advanced, while 168 ended unchanged.</p><br/><p>Shares in Titan Company Ltd (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/titan-industries\" id=\"1884bd3913eaa06c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"18433\">TITN</a></span>) rose to all time highs; up 2.19% or 85.70 to 3,995.00. Shares in Hindalco Industries Ltd. (NSE:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/hindalco-industries\" id=\"1884bd39141b6b17\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"18187\">HALC</a></span>) rose to all time highs; up 0.99% or 8.55 to 873.00. Shares in Titan Company Ltd (BO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/titan-industries?cid=18433\" id=\"1884bd3915026551\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"39709\">TITN</a></span>) rose to all time highs; up 2.19% or 85.50 to 3,994.00.</p><br/><p>The <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/india-vix\" id=\"1884bd39170ea8f7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"17942\">India VIX</a></span>, which measures the implied volatility of Nifty 50 options, was down 0.71% to 9.13 a new all time low.</p><br/><p>Gold Futures for February delivery was up 1.07% or 48.40 to $4,551.20 a troy ounce. Elsewhere in commodities trading, Crude oil for delivery in February rose 0.72% or 0.42 to hit $58.77 a barrel, while the February Brent oil contract rose 0.53% or 0.33 to trade at $62.57 a barrel.</p><br/><p>USD/INR was down 0.01% to 89.64, while EUR/INR rose 0.03% to 105.79.</p><br/><p>The US Dollar Index Futures was up 0.05% at 97.73.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (26, 'Nvidia, joining Big Tech deal spree, to license Groq technology, hire executives', 'Reuters', 'https://www.investing.com/news/stock-market-news/nvidia-joiningbig-tech-deal-spree-to-license-groq-technology-hire-executives-4423033', '<img src=\"https://i-invdn-com.investing.com/trkd-images/LYNXMPELBN0LU_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>(This December 24 story has been repeated without any changes to the text.)</p><br/><p>By Stephen Nellis</p><br/><p>Dec 24 (Reuters) - <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nvidia-corp\" id=\"1884bc9ab9c38b70\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6497\">Nvidia</a></span> has agreed to license chip technology from startup Groq and hire away its CEO, a veteran of Alphabet’s Google, Groq said in a blog post on Wednesday.</p><br/><p>The deal follows a familiar pattern in recent years where the world’s biggest technology firms pay large sums in deals with promising startups to take their technology and talent but stop short of formally acquiring the target.</p><br/><p>Groq specializes in what is known as inference, where artificial intelligence models that have already been trained respond to requests from users. While Nvidia dominates the market for training AI models, it faces much more competition in inference, where traditional rivals such as <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/adv-micro-device\" id=\"1884bc9aba29fa6d\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"8274\">Advanced Micro Devices</a></span> have aimed to challenge it as well as startups such as Groq and Cerebras Systems.</p><br/><p>Nvidia has agreed to a \"non-exclusive\" license to Groq’s technology, Groq said. It said its founder Jonathan Ross, who helped Google start its AI chip program, as well as Groq President Sunny Madra and other members of its engineering team, will join Nvidia.</p><br/><p>A person close to Nvidia confirmed the licensing agreement.</p><br/><p>Groq did not disclose financial details of the deal. CNBC reported that Nvidia had agreed to acquire Groq for $20 billion in cash, but neither Nvidia nor Groq commented on the report. Groq said in its blog post that it will continue to operate as an independent&nbsp;company with Simon Edwards as CEO and that its cloud business will continue operating.</p><br/><p>In similar recent deals, Microsoft’s top AI executive came through a $650 million deal with a startup that was billed as a licensing fee, and Meta spent $15 billion to hire Scale AI’s CEO without acquiring the entire firm. Amazon hired away founders from Adept AI, and Nvidia did a similar deal this year. The deals have faced scrutiny by regulators, though none has yet been unwound.</p><br/><p>\"Antitrust would seem to be the primary risk here, though structuring the deal as a non-exclusive license may keep the fiction of competition alive (even as Groq’s leadership and, we would presume, technical talent move over to Nvidia),\" Bernstein analyst Stacy Rasgon wrote in a note to clients on Wednesday after Groq’s announcement. And Nvidia CEO Jensen Huang’s \"relationship with the Trump administration appears among the strongest of the key US tech companies.\"</p><br/><p>Groq more than doubled its valuation to $6.9 billion from $2.8 billion in August last year, following a $750 million funding round in September.</p><br/><p>Groq is one of a number of upstarts that do not use external high-bandwidth memory chips, freeing them from the memory crunch affecting the global chip industry. The approach, which uses a form of on-chip memory called SRAM, helps speed up interactions with chatbots and other AI models but also limits the size of the model that can be served.</p><br/><p></p><br/><p>Groq’s primary rival in the approach is Cerebras Systems, which Reuters this month reported plans to go public as soon as next year. Groq and Cerebras have signed large deals in the Middle East.</p><br/><p>Nvidia’s Huang spent much of his biggest keynote speech of 2025 arguing that Nvidia would be able to maintain its lead as AI markets shift from training to inference.&nbsp;</p><br/><p></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (27, 'A year on, Jeju Air crash report delayed as families question probe’s credibility', 'Reuters', 'https://www.investing.com/news/stock-market-news/a-year-on-jeju-air-crash-report-delayed-as-families-question-probes-credibility-4422926', '<img src=\"https://i-invdn-com.investing.com/trkd-images/LYNXMPELBP044_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>By Hyunjoo Jin and Jungmin Ryu</p><br/><p>SEOUL, Dec 26 (Reuters) - A South Korean investigation into the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/jeju-air-co-ltd\" id=\"1884bc51c35197ec\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"960821\">Jeju Air</a></span> crash that killed 179 people is set to miss a one-year deadline to release a progress report, two officials said, as frustrated relatives of the victims continue to demand answers about what went wrong.</p><br/><p>The country’s accident investigation board will not be in a position to release the interim update by the first anniversary on Monday of the worst aircraft accident on South Korean soil, the two board officials said. They declined to be identified due to the sensitivity of the matter.</p><br/><p>On December 29, 2024, the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/boeing-co\" id=\"1884bc51c386a3cd\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"238\">Boeing 737-800</a></span> made an emergency belly landing at Muan airport, overshot the runway then slammed&nbsp;into a concrete embankment and erupted into a fireball, killing all but two of the 181 people on board.</p><br/><p>The government-led Aviation and Railway Accident Investigation Board said in a preliminary report in January that both of the plane’s engines sustained bird strikes.</p><br/><p>The pilots shut off the less-damaged engine after the bird strike, investigators said in a July update that was not released publicly due to objections from victims’ families.</p><br/><p>VICTIMS’ FAMILIES FRUSTRATED</p><br/><p>Some of the family members said investigators appeared to blame the pilots without exploring other factors, such as the concrete structure beyond the end of the runway that likely made the disaster far more deadly.</p><br/><p>\"It feels like all kinds of doubts are just growing bigger and bigger. In the meantime, a year has gone by, and it feels like the frustration is only continuing to build,\" said Ryu Kum-Ji, a 42-year-old woman who lost both of her parents in the crash.</p><br/><p>She joined other family members who shaved their heads and staged a protest in front of a presidential office, calling for an independent and transparent probe.</p><br/><p>Missteps by the transport ministry, which oversees the investigation board, could also be a factor in the accident, Ryu said.</p><br/><p>A transport ministry official told bereaved family members this month that it would examine their concerns.</p><br/><p>\"We take seriously your concerns saying that government’s efforts were not sufficient in the process of (finding the truth),\" the second vice minister of the transport ministry said. \"The government will stand by the bereaved families and take a closer look.\"</p><br/><p>South Korea’s parliament will launch an independent probe into the crash on Tuesday.</p><br/><p>REPORT DELAYED</p><br/><p>Under the U.N. aviation body’s rules, a final report is expected within a year of an accident, and if that is not possible, an interim statement should be made public on every anniversary detailing the investigation’s progress and any safety issues raised.</p><br/><p>But the investigation board is not planning to release an update yet because of pending legislation designed to ensure its independence, said the two officials.</p><br/><p>Lawmakers have proposed replacing board members and transferring oversight from the transport ministry to the prime minister’s office.</p><br/><p>\"We will respect the decision of the newly formed committee regarding the timing of the interim statement’s publication,\" said one of the board officials.</p><br/><p>South Korea’s anti-corruption body found in a report this week that the concrete embankment at Muan airport violated local and global standards that call for such structures to be \"frangible\" so they give way in case of impact. That meant it could \"cause fatal damage to aircraft and occupants.\"</p><br/><p></p><br/><p>The board had planned public hearings in early December, but delayed them at the request of the victims’ families and lawmakers. Police are also investigating the accident.</p><br/><p>\"All we want is for authorities to admit they were wrong if they did wrong, and apologise. Apology and a proper disclosure of the truth...that is what we want,\" Ryu said.</p><br/><p></p><br/><p></p><br/><p></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (28, 'Shimadzu to acquire Czech microscope maker Tescan for $678 million', 'Investing.com', 'https://www.investing.com/news/stock-market-news/shimadzu-to-acquire-czech-microscope-maker-tescan-for-678-million-93CH-4423031', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPED0C0KP_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- Japanese scientific equipment manufacturer <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/shimadzu-corp\" id=\"1884bba0a74b74c2\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"946260\">Shimadzu</a></span> has reached an agreement to acquire European electron microscope maker Tescan Group for $678 million from private equity firm Carlyle.</p><br/><p>The deal, announced on Wednesday, is expected to close in the first half of 2026, according to Shimadzu. The Japanese company plans to finance the acquisition through a combination of cash reserves and external borrowings.</p><br/><p>Tescan Group, founded in 1991 in the Czech Republic, specializes in analytical instrumentation with a focus on electron microscopes. The company’s product portfolio includes scanning electron microscopes (SEM), focused ion beam scanning electron microscopes (FIB-SEM), transmission electron microscopes (TEM), micro-CT systems, and laser processing equipment.</p><br/><p>The acquisition price represents approximately ¥105.8 billion based on an exchange rate of ¥156 to the U.S. dollar.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (29, 'Hirose Electric announces new share buyback plan worth ¥15 billion', 'Investing.com', 'https://www.investing.com/news/stock-market-news/hirose-electric-announces-new-share-buyback-plan-worth-15-billion-93CH-4423030', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEB280W7_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/hirose-electric-co-ltd\" id=\"1884bb9b79f6fa11\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"946224\">Hirose Electric</a></span> announced a new share buyback program after market close on Wednesday. The company plans to repurchase up to 1 million shares, representing 3.03% of outstanding shares excluding treasury stock, or up to ¥15 billion.</p><br/><p>The acquisition period for this new buyback is scheduled to run from January 5 to July 31, 2026.</p><br/><p>This announcement follows Hirose Electric’s previous commitment to repurchase ¥60 billion worth of shares during the fiscal years 2026-2029. The company has already acquired ¥15 billion worth of shares between August 5 and November 14, 2025.</p><br/><p>The additional buyback announcement within the current fiscal year was unexpected and comes after the company’s share price has been underperforming since its second-quarter earnings release for fiscal year 2026.</p><br/><p>Prior to these recent initiatives, Hirose Electric had implemented a ¥40 billion share buyback scheme between fiscal years 2022 and 2025, which was completed by fiscal year 2024.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (30, 'Russia’s VTB maintains 2025 profit target as corporate debt restructuring underway', 'Reuters', 'https://www.investing.com/news/stock-market-news/russias-vtb-says-jannov-net-profit-down-33-maintains-2025-profit-forecast-4423021', '<img src=\"https://i-invdn-com.investing.com/trkd-images/LYNXMPELBP08B_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>MOSCOW, Dec 26 (Reuters) - Russia’s second largest bank <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/vtb_rts\" id=\"1884bb6123fde662\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13725\">VTB</a></span> maintained its net profit target of 500 billion roubles ($6.4 billion) for 2025 after reporting results for January-November on Friday and saying it was engaged in restructuring talks with corporate clients.</p><br/><p>VTB said its net profit for 11 months of the year fell by 3.3% year-on-year to 437.2 billion roubles ($5.61 billion) with net interest income up 2.5-fold from November last year. <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/vtb_rts\" id=\"1884bb61244783af\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13725\">VTB shares</a></span> were up 0.6% on the Moscow Exchange.</p><br/><p>Russian banks have maintained strong profits in 2025 despite a slowdown in corporate lending growth, driven by a general cooling of the economy, with gross domestic product (GDP) growth expected to fall to around 1% from 4.3% last year.</p><br/><p>\"We targeted 500 billion roubles of net profit for the year and we are maintaining this target,\" said First Deputy CEO Dmitry Pyanov. In 2024, VTB reported net profit of 550 billion roubles.</p><br/><p>Some major Russian corporations, including giant Russian Railways, the country’s biggest employer, are seeking to restructure their debt due to high servicing costs pushed up by the central bank’s tough monetary policy to fight inflation.</p><br/><p>Pyanov said that share of restructured corporate loans has grown to 11% of the total portfolio as of the end of November from 10% in the previous month as the bank was negotiating convenient payment schedules with clients.</p><br/><p>Pyanov said that the ongoing restructuring of corporate loans will have no immediate impacts on <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/vtb_rts\" id=\"1884bb6124742437\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"13725\">VTB’s</a></span> reserves and other indicators since the bank is not losing its income on interest. VTB held 17 trillion roubles ($218.79 billion) in corporate debt in November.</p><br/><p></p><br/><p>\"The overwhelming majority of these restructurings occur without any losses for the bank, so in this situation it affects us in terms of the workload. That is, we have to participate in negotiations and attend meetings,\" Pyanov said.</p><br/><p>($1 = 77.7000 roubles)</p><br/><p></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (31, 'Coupang shares jump after company identifies ex-employee in data breach', 'Investing.com', 'https://www.investing.com/news/stock-market-news/coupang-shares-jump-after-company-identifies-exemployee-in-data-breach-93CH-4423026', '<img src=\"https://i-invdn-com.investing.com/news/LYNXNPEAB20I9_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/coupang-llc\" id=\"1884bb185864e2e6\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"1171204\">Coupang</a></span> shares rose 6.5% in U.S. premarket trading on Friday after the company identified the former employee responsible for accessing personal data of 33 million customers.</p><br/><p>According to Yonhap News, the e-commerce company has retrieved all hard disk drives and devices used by the ex-worker who was involved in South Korea’s biggest-ever data leak.</p><br/><p>The report, citing the company, stated that while the former employee accessed data of 33 million customers, personal information of only 3,000 customers was actually saved.</p><br/><p>Coupang confirmed that the data was not shared with any third party. Additionally, sensitive information such as payment details, login credentials, and personal customs clearance codes remained secure and were not accessed during the breach.</p><br/><p>The positive development comes as Coupang shares have fallen 19% in December amid the ongoing investigation into the data breach.</p><br/><p><em>This article was generated with the support of AI and reviewed by an editor. For more information see our T&amp;C.</em></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (32, 'Samsung stock soars after plans to mass produce HBM4 for Nvidia AI chips', 'Investing.com', 'https://www.investing.com/news/stock-market-news/samsung-stock-soars-after-plans-to-mass-produce-hbm4-for-nvidia-ai-chips-4423025', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEB3S09S_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com -- <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/samsung-electronics-co-ltd\" id=\"1884b9dd72bfcbca\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"43433\">Samsung Electronics (KS:005930)</a></span> shares jumped 5.3% in Seoul trading today after reports emerged that the tech giant will begin mass production of next-generation HBM4 memory chips in February at its Pyeongtaek campus in South Korea.</p><br/><p></p><br/><p></p><br/><p><span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/sk-hynix-inc\" id=\"1884b9dd7312bd24\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"43430\">SK Hynix (KS:000660)</a></span>, which also plans to manufacture the advanced memory chips, saw its stock rise 1.9% on the news.</p><br/><p>According to the Seoul Economic Daily, citing unidentified industry sources, SK Hynix will commence HBM4 production at its M16 fab facility in February.</p><br/><p>The HBM4 chips will be utilized in Nvidia’s next-generation artificial intelligence processors, codenamed \"Rubin.\"</p><br/><p>SK Hynix has already made significant progress in the development process, having provided HBM4 samples to <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nvidia-corp\" id=\"1884b9dd734e8f97\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"6497\">NVIDIA (NASDAQ:NVDA)</a></span> in March and established its mass production system in September.</p><br/><p>Morgan Stanley analysts said recently that they remain bullish on the outlook for Samsung’s memory business.</p><br/><p>\"We expect Samsung’s memory profits to grow 310% in 2026, approaching the W100tr profit mark,\" analysts led by Shawn Kim wrote in a client note.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (33, 'Asia stocks: Japan’s TOPIX hits record high with Tokyo CPI in focus', 'Investing.com', 'https://www.investing.com/news/stock-market-news/asia-stocks-japans-topix-hits-record-high-with-tokyo-cpi-in-focus-4422952', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEA620A7_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com-- Most Asian stock markets rose on Friday in thin year-end trading, while Japan’s <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/topix\" id=\"1884b97371aa5485\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"41042\">TOPIX</a></span> index notched a record high with focus on Tokyo’s consumer inflation and the country’s factory output data.</p><br/><p>Trading volumes across the region remained light as several major markets were closed, including Australia, New Zealand, and Hong Kong.</p><br/><p>Wall St futures were also muted during Asia hours after gains earlier this week.</p><br/><p>Japanese shares outperformed the region, with the TOPIX index climbing over 1% to a record high. The&nbsp;<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/japan-ni225\" id=\"1884b973720997dc\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"178\">Nikkei 225</a></span> rose 0.6%.</p><br/><p>Gains were underpinned by strength in technology stocks as investors weighed a series of domestic economic releases.</p><br/><p>Data showed inflation in Tokyo eased in December from the previous month, but remained above the Bank of Japan’s target, reinforcing expectations that the central bank could continue normalising monetary policy.&nbsp;</p><br/><p>Additional data highlighted the mixed nature of Japan’s economic recovery. Factory output declined in November, reflecting weakness in manufacturing sectors such as autos and electronics, while retail sales rose, pointing to resilient consumer spending.&nbsp;</p><br/><p>Elsewhere in the region, South Korea’s <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/kospi\" id=\"1884b973726dea37\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"37426\">KOSPI</a></span> rose 0.5% on gains in technology shares. Chipmakers rebounded further, tracking overnight strength in Wall Street technology stocks amid renewed optimism around artificial intelligence investment and demand.</p><br/><p dir=\"ltr\">China’s blue chip <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/csi300\" id=\"1884b97372ac50f6\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"940801\">Shanghai Shenzhen CSI 300</a></span>&nbsp;rose 0.3%, while the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/shanghai-composite\" id=\"1884b9737308dfb2\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"40820\">Shanghai Composite</a></span>&nbsp;index gained 0.2%.</p><br/><p dir=\"ltr\">India’s <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/s-p-cnx-nifty\" id=\"1884b97373825af6\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"17940\">Nifty 50</a></span> edged 0.3% lower, while Singapore’s <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/singapore-straits-time\" id=\"1884b97373b59a78\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"40006\">Straits Times Index</a></span> traded largely flat.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (34, 'Silver tops $75 as gold and platinum surge to records', 'Reuters', 'https://www.investing.com/news/stock-market-news/silver-tops-75-as-gold-and-platinum-surge-to-records-4423023', '<img src=\"https://i-invdn-com.investing.com/trkd-images/LYNXMPELBP04F_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>By Sherin Elizabeth Varghese</p><br/><p>Dec 26 (Reuters) - Silver hit $75 for the first time on Friday, with <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/currencies/xau-usd\" id=\"1884b95cafcad017\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"68\">gold</a></span> and platinum too striking record highs, as speculative bets, expectations for more U.S. rate cuts, and rising geopolitical tensions powered precious metals.</p><br/><p>Spot gold rose 0.8% to $4,515.73 per ounce, as of 0818 GMT, after touching a record $4,530.60 earlier. U.S. gold futures for February delivery climbed 0.9% to $4,545.10.&nbsp;</p><br/><p>Spot <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/currencies/xag-usd\" id=\"1884b95cb01b8186\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"69\">silver</a></span> jumped 3.8% to $74.68 per ounce, after touching an all-time high of $75.14.</p><br/><p>\"Momentum-driven and speculative players have been powering the rally in gold and silver since early December, with thin year-end liquidity, expectations of prolonged U.S. rate cuts, a weaker dollar and a flare-up in geopolitical risks combining to push precious metals to fresh record highs,\" said Kelvin Wong, senior market analyst at OANDA. [USD/]</p><br/><p>\"Looking ahead into the first half of 2026, gold could move towards the $5,000 level, while silver has the potential to reach around $90.\"</p><br/><p>Gold staged a strong rally this year, recording its biggest annual gain since 1979, fueled by Federal Reserve policy easing, geopolitical uncertainty, strong central bank demand, rising ETF holdings, and ongoing de-dollarisation.</p><br/><p>Meanwhile, gold discounts in India hit a more than six-month high as record prices curbed retail buying, while China’s discounts retreated from last week’s five-year peak. [GOL/AS]</p><br/><p>Silver soared 158% year-to-date, outpacing gold’s nearly 72% gain, on structural deficits, its listing as a U.S. critical mineral, and robust industrial demand.&nbsp;</p><br/><p>With traders pricing in two U.S. rate cuts next year, non-yielding assets like gold are likely to remain well-supported in a low-interest-rate environment.</p><br/><p>On the geopolitical front, the U.S. is focusing on enforcing a \"quarantine\" of Venezuelan oil for the next two months. On Thursday, it struck Islamic State militants in northwest Nigeria over attacks on local Christian communities.</p><br/><p>Spot platinum rose 5.8% to $2,349.65 per ounce, after touching an all-time high of $2,448.25 earlier, while <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/commodities/palladium\" id=\"1884b95cb06f6897\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"8883\">palladium</a></span> climbed 7% to $1,801.25, following a three-year high in the previous session. All precious metals were headed for weekly gains.</p><br/><p></p><br/><p><span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/commodities/platinum\" id=\"1884b95cb0a7cd9b\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"8910\">Platinum</a></span> and palladium, widely used in automotive catalytic converters, have surged on tight supply, tariff uncertainty, and rotation from gold investment demand, with platinum up roughly 160% and palladium more than 90% year-to-date.</p><br/><p>\"Platinum prices are being supported by strong industrial demand, and stockists in the U.S. have been covering positions amid sanctions-related concerns, which is helping keep prices elevated,\" said Jigar Trivedi, senior research analyst at Reliance Securities based in Mumbai.</p><br/><p></p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
INSERT INTO `stock_news` (`id`, `title`, `provider`, `link`, `content`, `create_by`, `create_time`, `update_by`, `update_time`) VALUES (35, 'Japan stocks higher at close of trade; Nikkei 225 up 0.62%', 'Investing.com', 'https://www.investing.com/news/stock-market-news/japan-stocks-higher-at-close-of-trade-nikkei-225-up-062-4422969', '<img src=\"https://i-invdn-com.investing.com/news/LYNXMPEB40170_L.jpg\" style=\"height: 230px; width: 80%; object-fit: contain; display: block; margin: 0 auto;\"><br/><p>Investing.com – Japan stocks were higher after the close on Friday, as gains in the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/n500-real-estate\" id=\"1884b1c35b3f8f2b\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"946067\">Real Estate</a></span>, <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/n500-banking\" id=\"1884b1c35b8aea7c\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"946042\">Banking</a></span> and <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/n500-textiles---apparel\" id=\"1884b1c35be1e5e7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"946075\">Textile</a></span> sectors led shares higher.</p><br/><p>At the close in Tokyo, the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/japan-ni225\" id=\"1884b1c35c185432\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"178\">Nikkei 225</a></span> added 0.62%.</p><br/><p>The best performers of the session on the <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/japan-ni225\" id=\"1884b1c35c185432\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"178\">Nikkei 225</a></span> were Sapporo Holdings Ltd. (TYO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/sapporo-holdings-ltd.\" id=\"1884b1c35c93f18e\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44179\">2501</a></span>), which rose 2.49% or 201.00 points to trade at 8,271.00 at the close. Meanwhile, DeNA Co Ltd (TYO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/dena-co-ltd\" id=\"1884b1c35cb9de47\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"102045\">2432</a></span>) added 2.39% or 61.00 points to end at 2,618.00 and Nintendo Co Ltd (TYO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/nintendo-ltd\" id=\"1884b1c35cf227e7\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"946265\">7974</a></span>) was up 2.32% or 245.00 points to 10,795.00 in late trade.</p><br/><p>The worst performers of the session were Sumitomo Electric Industries Ltd. (TYO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/sumitomo-electric-industries-ltd.\" id=\"1884b1c35d223477\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44126\">5802</a></span>), which fell 4.36% or 285.00 points to trade at 6,255.00 at the close. Mitsui Mining and Smelting Co. (TYO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/mitsui-mining-and-smelting-co.\" id=\"1884b1c35d544fb0\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44315\">5706</a></span>) declined 3.00% or 535.00 points to end at 17,325.00 and Fujikura Ltd. (TYO:<span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/equities/fujikura-ltd.\" id=\"1884b1c35d8b5a93\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"44131\">5803</a></span>) was down 2.61% or 460.00 points to 17,160.00.</p><br/><p>Rising stocks outnumbered declining ones on the Tokyo Stock Exchange by 1867 to 1727 and 251 ended unchanged.</p><br/><p>The <span class=\"aqPopupWrapper js-hover-me-wrapper\"><a href=\"/indices/nikkei-volatility\" id=\"1884b1c35dea1e76\" class=\"aqlink js-hover-me\" hoverme=\"aql\" data-pairid=\"28878\">Nikkei Volatility</a></span>, which measures the implied volatility of Nikkei 225 options, was down 16.13% to 18.77 a new 52-week low.</p><br/><p>Crude oil for February delivery was up 0.26% or 0.15 to $58.50 a barrel. Elsewhere in commodities trading, Brent oil for delivery in February rose 0.19% or 0.12 to hit $62.36 a barrel, while the February Gold Futures contract rose 0.87% or 39.05 to trade at $4,541.85 a troy ounce.</p><br/><p>USD/JPY was up 0.23% to 156.29, while EUR/JPY rose 0.27% to 184.08.</p><br/><p>The US Dollar Index Futures was up 0.01% at 97.69.</p>', 'system', '2025-12-26 23:21:12', NULL, '2025-12-26 23:21:12');
COMMIT;

-- ----------------------------
-- Table structure for stock_subscription
-- ----------------------------
DROP TABLE IF EXISTS `stock_subscription`;
CREATE TABLE `stock_subscription` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT 'id',
  `order_no` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '订单号',
  `user_id` bigint DEFAULT NULL COMMENT '用户id',
  `top_user_id` bigint DEFAULT NULL COMMENT '上级userid',
  `name` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '股票名称',
  `buy_price` decimal(20,4) DEFAULT NULL COMMENT '购买价格',
  `symbol` varchar(30) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '股票代码',
  `apply_nums` decimal(20,4) DEFAULT NULL COMMENT '申购数量',
  `allotment_quantity` decimal(20,4) DEFAULT NULL COMMENT '中签数量',
  `status` int NOT NULL DEFAULT '1' COMMENT '状态：1、已认购，2、未中签，3、已中签，4、已缴纳 5.已转持仓',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `submit_time` datetime DEFAULT NULL COMMENT '提交时间',
  `allotment_time` datetime DEFAULT NULL COMMENT '申购时间',
  `fix_time` datetime DEFAULT NULL COMMENT '双融确定时间',
  `remarks` varchar(200) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '备注',
  `type` int DEFAULT NULL COMMENT '1 新股 2配售',
  `stock_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '新股类型',
  `ipo_id` bigint DEFAULT NULL COMMENT 'IPO配置id',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_id` (`id`) USING BTREE,
  UNIQUE KEY `uk_order_no` (`order_no`) USING BTREE,
  KEY `idx_user_id` (`user_id`) USING BTREE,
  KEY `idx_top_user_id` (`top_user_id`) USING BTREE,
  KEY `idx_symbol` (`symbol`) USING BTREE,
  KEY `idx_status` (`status`) USING BTREE,
  KEY `idx_type` (`type`) USING BTREE,
  KEY `idx_create_time` (`create_time`) USING BTREE,
  KEY `idx_allotment_time` (`allotment_time`) USING BTREE,
