-- ----------------------------
-- Table structure for user_pendingorder
-- ----------------------------
DROP TABLE IF EXISTS `user_pendingorder`;
CREATE TABLE `user_pendingorder` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键，自增ID',
  `user_id` int unsigned DEFAULT NULL COMMENT '用户ID，关联users表',
  `stock_id` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票代码',
  `buy_num` int unsigned DEFAULT NULL COMMENT '买入数量',
  `buy_type` int unsigned DEFAULT NULL COMMENT '订单类型',
  `lever` int unsigned DEFAULT NULL COMMENT '杠杆倍数',
  `profit_target` decimal(18,3) DEFAULT NULL COMMENT '止盈价格',
  `stop_target` decimal(18,3) DEFAULT NULL COMMENT '止损价格',
  `now_price` decimal(18,3) DEFAULT NULL COMMENT '当前价格',
  `target_price` decimal(18,3) DEFAULT NULL COMMENT '目标价格',
  `add_time` datetime DEFAULT NULL COMMENT '订单添加时间',
  `status` tinyint unsigned DEFAULT NULL COMMENT '状态（0: 已挂单, 1: 买入成功, 2: 买入失败）',
  `fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '买入失败原因',
  `stock_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票类型',
  `order_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL COMMENT '订单编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_order_no` (`order_no`) USING BTREE COMMENT '订单编号唯一索引',
  KEY `idx_user_id` (`user_id`) USING BTREE COMMENT '用户ID索引',
  KEY `idx_stock_type` (`stock_type`) USING BTREE COMMENT '股票类型索引'
) ENGINE=InnoDB AUTO_INCREMENT=2 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户挂单表';

-- ----------------------------
-- Records of user_pendingorder
-- ----------------------------
BEGIN;
INSERT INTO `user_pendingorder` (`id`, `user_id`, `stock_id`, `buy_num`, `buy_type`, `lever`, `profit_target`, `stop_target`, `now_price`, `target_price`, `add_time`, `status`, `fail_reason`, `stock_type`, `order_no`) VALUES (1, 6, '4045', 1, 1, 1, NULL, NULL, 935.850, 43500.000, '2025-11-26 01:27:19', 0, NULL, 'US', '1993537020905037824');
COMMIT;

-- ----------------------------
-- Table structure for user_position
-- ----------------------------
DROP TABLE IF EXISTS `user_position`;
CREATE TABLE `user_position` (
  `id` int unsigned NOT NULL AUTO_INCREMENT COMMENT '主键，自增ID',
  `position_type` int unsigned DEFAULT NULL COMMENT '持仓类型',
  `position_sn` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '持仓编号',
  `user_id` int unsigned DEFAULT NULL COMMENT '用户ID',
  `nick_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '用户昵称',
  `agent_id` int unsigned DEFAULT NULL COMMENT '代理ID',
  `stock_name` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票名称',
  `stock_code` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票代码',
  `stock_type` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票类型',
  `stock_gid` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票全局ID',
  `stock_spell` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票拼音',
  `buy_order_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '买入订单ID',
  `buy_order_time` datetime DEFAULT NULL COMMENT '买入订单时间',
  `buy_order_price` decimal(18,3) DEFAULT NULL COMMENT '买入订单价格',
  `sell_order_id` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '卖出订单ID',
  `sell_order_time` datetime DEFAULT NULL COMMENT '卖出订单时间',
  `sell_order_price` decimal(18,3) DEFAULT NULL COMMENT '卖出订单价格',
  `sell_fail_reason` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '卖出失败原因',
  `profit_target_price` decimal(18,3) DEFAULT NULL COMMENT '目标盈利价格',
  `stop_target_price` decimal(18,3) DEFAULT NULL COMMENT '止损价格',
  `order_direction` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '订单方向（如买入/卖出）',
  `order_num` decimal(10,3) DEFAULT NULL COMMENT '订单数量',
  `order_lever` int unsigned DEFAULT NULL COMMENT '杠杆倍数',
  `order_total_price` decimal(18,3) NOT NULL COMMENT '订单总金额',
  `order_fee` decimal(18,3) NOT NULL COMMENT '订单手续费',
  `order_spread` decimal(18,3) NOT NULL COMMENT '点差费用',
  `order_stay_fee` decimal(18,3) NOT NULL COMMENT '持仓过夜费',
  `order_stay_days` int unsigned NOT NULL DEFAULT '0' COMMENT '持仓天数',
  `profit_and_lose` decimal(18,3) NOT NULL COMMENT '盈亏金额',
  `all_profit_and_lose` decimal(18,3) DEFAULT NULL COMMENT '总盈亏金额',
  `is_lock` tinyint unsigned DEFAULT '0' COMMENT '是否锁仓（0: 未锁仓, 1: 锁仓）',
  `lock_msg` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '锁仓信息',
  `stock_plate` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '股票板块',
  `spread_rate_price` decimal(18,3) DEFAULT NULL COMMENT '点差费用',
  `margin_add` decimal(18,3) DEFAULT NULL COMMENT '追加保证金',
  `status` char(1) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '状态（1: 持仓中, 2: 正在平仓, 3: 已平仓, 4: 平仓失败）',
  `lot_unit` int unsigned DEFAULT NULL COMMENT '每手单位数量',
  `pendingorder_no` varchar(32) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL COMMENT '挂单编号',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_position_sn` (`position_sn`) USING BTREE COMMENT '持仓编号唯一索引',
  UNIQUE KEY `uk_buy_order_id` (`buy_order_id`) USING BTREE COMMENT '买入订单ID唯一索引',
  KEY `idx_stock_type` (`stock_type`) USING BTREE COMMENT '股票类型索引',
  KEY `idx_status` (`status`) USING BTREE COMMENT '状态索引',
  KEY `idx_user_id` (`user_id`) USING BTREE COMMENT '用户ID索引',
  KEY `idx_pendingorder_no` (`pendingorder_no`) USING BTREE COMMENT '挂单编号索引'
) ENGINE=InnoDB AUTO_INCREMENT=17 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci COMMENT='用户持仓表';

