-- ----------------------------
-- Table structure for user_quotation_control
-- ----------------------------
DROP TABLE IF EXISTS `user_quotation_control`;
CREATE TABLE `user_quotation_control` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `user_id` bigint NOT NULL COMMENT '用户ID',
  `symbol` varchar(60) NOT NULL COMMENT '股票代码',
  `stock_type` varchar(20) NOT NULL COMMENT '市场类型(US/CN/IN等)',
  `floating` decimal(20,8) DEFAULT '0.00000000' COMMENT '价格浮动值(正数上浮,负数下浮)',
  `is_active` tinyint DEFAULT '1' COMMENT '是否启用(0=禁用,1=启用)',
  `remark` varchar(255) DEFAULT NULL COMMENT '备注',
  `created_at` datetime DEFAULT CURRENT_TIMESTAMP,
  `updated_at` datetime DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_symbol` (`user_id`,`symbol`,`stock_type`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='用户行情调控表';

